INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C1','math',2,2,'u5',2,'자료를 분류하여 표로 나타내기 — 기준을 정해 같은 것끼리 모으고, ／ 표시를 하며 빠짐없이 세어 수로 적기',ARRAY['2수04-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C2','math',2,2,'u5',2,'표의 합계와 편리한 점 — 항목별 수를 모두 더한 합계가 전체 수임을 알고, 자료와 표가 각각 무엇을 알기 좋은지 말하기',ARRAY['2수04-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C3','math',2,2,'u5',3,'자료를 조사하는 방법 — 말하기·손 들기·이름 붙이기 등 알맞은 방법을 고르고, 빠진 사람 없이 조사하기',ARRAY['2수04-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C4','math',2,2,'u5',3,'조사한 자료를 표로 나타내기 — 제목·항목·수·합계를 갖추어 표를 만들고, ／ 표시를 세어 빈칸을 채우며 합계로 확인하기',ARRAY['2수04-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C5','math',2,2,'u5',4,'그래프를 그리는 차례 — 가로·세로에 나타낼 것을 정하고 가장 큰 수만큼 칸을 나누며, 가로와 세로를 바꾸어도 수는 같음을 알기',ARRAY['2수04-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C6','math',2,2,'u5',4,'맨 아래부터 빠짐없이 그리기 — ◯·×·／를 한 칸에 하나씩 맨 아래부터 빠짐없이 그리고, 표와 그래프의 수가 같게 옮기며 잘못 그린 곳 찾기',ARRAY['2수04-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C7','math',2,2,'u5',5,'표와 그래프 읽기 — 표에서 수와 합계를, 그래프에서 많고 적음을 읽고 차이·「n보다 많은」을 찾으며 둘의 편리한 점을 가리기',ARRAY['2수04-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C8','math',2,2,'u5',6,'조사하여 표와 그래프로 나타내기 — 우리 반을 조사해 표와 그래프로 옮기고, 알게 된 것을 그대로 적어 전하기',ARRAY['2수04-03']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X01','math',2,'u5',ARRAY['M2-2-u5-C1','M2-2-u5-C2','M2-2-u5-C4','M2-2-u5-C6','M2-2-u5-C7','M2-2-u5-C8']::text[],'세다가 빠뜨리거나 두 번 세어 수가 하나 어긋난다','센 것에 ／ 표시를 하며 하나씩 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X02','math',2,'u5',ARRAY['M2-2-u5-C1','M2-2-u5-C4','M2-2-u5-C7']::text[],'자료에서 묻는 항목이 아닌 것까지 세거나 이웃 칸의 수를 읽는다','묻는 항목 이름에 동그라미를 치고 그것만 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X03','math',2,'u5',ARRAY['M2-2-u5-C2','M2-2-u5-C4','M2-2-u5-C7','M2-2-u5-C8']::text[],'합계와 한 칸의 수를 섞는다 — 가장 큰 수를 합계로, 합계를 한 항목의 수로 답한다','합계는 모든 칸을 더한 수 — 한 칸보다 언제나 커요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X04','math',2,'u5',ARRAY['M2-2-u5-C2','M2-2-u5-C7']::text[],'「몇 가지」와 「몇 명」을 섞는다 — 항목 수를 학생 수로, 학생 수를 가짓수로 답한다','가지는 칸의 수, 명은 사람 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X05','math',2,'u5',ARRAY['M2-2-u5-C2','M2-2-u5-C4']::text[],'표의 빈칸을 합계에서 빼지 않고 나머지 칸의 합을 그대로 쓴다','합계 − 나머지 칸의 합 = 빈칸') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X06','math',2,'u5',ARRAY['M2-2-u5-C1','M2-2-u5-C4','M2-2-u5-C8']::text[],'／ 표시를 셀 때 다섯 묶음을 4나 6으로 세거나 한 줄을 통째로 빠뜨린다','／／／／／ 한 묶음은 5 — 5, 10 하고 묶음부터 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X07','math',2,'u5',ARRAY['M2-2-u5-C7','M2-2-u5-C8']::text[],'많고 적음을 수가 아니라 칸의 자리나 이름으로 판단한다(맨 앞 칸이 가장 많다)','수를 보고 견주기 — 그래프는 높이, 표는 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X08','math',2,'u5',ARRAY['M2-2-u5-C2','M2-2-u5-C7']::text[],'「몇 더 많은」을 묻는데 두 수를 더하거나, 「모두 몇」을 묻는데 뺀다','더 많은 → 빼기, 모두 → 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X09','math',2,'u5',ARRAY['M2-2-u5-C1','M2-2-u5-C2','M2-2-u5-C3','M2-2-u5-C4','M2-2-u5-C5','M2-2-u5-C6','M2-2-u5-C7','M2-2-u5-C8']::text[],'묻는 말을 거꾸로 읽는다 — 많은↔적은, 아닌↔맞는, 바른↔잘못된','물음의 「가장·아닌·잘못」에 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X10','math',2,'u5',ARRAY['M2-2-u5-C5','M2-2-u5-C6']::text[],'◯를 위에서부터 그리거나 중간 칸을 건너뛰어 그린다','맨 아래 칸부터 한 칸에 하나씩 빠짐없이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X11','math',2,'u5',ARRAY['M2-2-u5-C6','M2-2-u5-C8']::text[],'표의 수와 그래프의 ◯ 수를 다르게 옮긴다(하나 많거나 적게)','표의 수를 짚어 가며 ◯를 하나씩 세어 그리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X12','math',2,'u5',ARRAY['M2-2-u5-C5']::text[],'그래프의 칸 수를 합계나 항목 수로 잡는다(칸이 모자라거나 빈 칸이 많이 남음)','세로 칸 수 = 가장 큰 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X13','math',2,'u5',ARRAY['M2-2-u5-C5','M2-2-u5-C6']::text[],'한 그래프에 기호를 섞어 쓰거나, 가로와 세로를 바꾸면 수도 달라진다고 여긴다','기호는 한 가지로 — 자리를 바꿔도 수는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X14','math',2,'u5',ARRAY['M2-2-u5-C7']::text[],'「n보다 많은」에 딱 n인 것을 넣는다(경곗값)','n인 칸 위에 선을 긋고 그 위에 ◯가 있는 것만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X15','math',2,'u5',ARRAY['M2-2-u5-C1','M2-2-u5-C3','M2-2-u5-C4','M2-2-u5-C8']::text[],'조사·표 만들기의 절차를 어긴다 — 기준 없이 모으기, 몇 명만 조사하기, 제목·합계 빠뜨리기, 합계를 마음대로 고치기','모두 조사 → 기준에 따라 모으기 → 제목·항목·수·합계') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X16','math',2,'u5',ARRAY['M2-2-u5-C2','M2-2-u5-C7','M2-2-u5-C8']::text[],'자료·표·그래프가 각각 알기 좋은 것을 뒤바꾼다(표에서 누가 골랐는지 안다, 그래프가 수를 알기 좋다)','자료는 누가, 표는 수와 합계, 그래프는 많고 적음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X17','math',2,'u5',ARRAY['M2-2-u5-C7','M2-2-u5-C8']::text[],'표와 그래프에 나타나지 않은 까닭·느낌·짐작을 「알 수 있는 내용」이라고 쓴다(흐린 날이 많으니 12월은 날마다 추웠다, 공기놀이가 가장 재미있는 놀이다)','표와 그래프에 있는 것은 항목별 수와 많고 적음뿐 — 그 안에 없는 까닭이나 느낌은 알 수 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X18','math',2,'u5',ARRAY['M2-2-u5-C5','M2-2-u5-C6']::text[],'그래프의 ◯·×·／ 크기나 모양이 수를 나타낸다고 여긴다(◯를 크게 그리면 더 많은 것이다)','기호 하나는 크기와 상관없이 하나 — 몇 개인지, 얼마나 높이 쌓였는지로 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_basic#1','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',1,'mc','auto','선생님이 칠판에 「친구들의 생각이 궁금해요.」라고 쓰고 조사할 주제 네 가지를 적었어요. 칠판에 적힌 주제가 아닌 것은 어느 것인가요?',ARRAY['M2-2-u5-X09']::text[],true,'{"seq":1,"concept":"M2-2-u5-C1","difficulty":1,"kind":"mc","stem":"선생님이 칠판에 「친구들의 생각이 궁금해요.」라고 쓰고 조사할 주제 네 가지를 적었어요. 칠판에 적힌 주제가 아닌 것은 어느 것인가요?","options":[{"t":"좋아하는 음식","correct":true},{"t":"좋아하는 전통 놀이","mis":"M2-2-u5-X09"},{"t":"하고 싶은 교실 놀이","mis":"M2-2-u5-X09"}],"explanation":["칠판에는 1. 2학년 때 즐거웠던 활동, 2. 좋아하는 동물, 3. 좋아하는 전통 놀이, 4. 하고 싶은 교실 놀이가 적혀 있어요.","좋아하는 음식은 칠판에 없어요.","「아닌 것」을 묻는지 물음을 다시 읽어요."],"variant_rule":{"alt":[{"stem":"칠판의 「친구들의 생각이 궁금해요.」에 첫 번째로 적힌 조사 주제는 무엇인가요?","options":[{"t":"2학년 때 즐거웠던 활동","correct":true},{"t":"좋아하는 동물","mis":"M2-2-u5-X02"},{"t":"하고 싶은 교실 놀이","mis":"M2-2-u5-X02"}],"explanation":["칠판의 주제는 차례로 즐거웠던 활동, 좋아하는 동물, 좋아하는 전통 놀이, 하고 싶은 교실 놀이예요.","첫 번째는 「2학년 때 즐거웠던 활동」이에요.","번호를 짚어 가며 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_basic#2','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',1,'sa','auto','자료를 보세요. 놀이 한마당이 즐거웠던 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u5-C1","difficulty":1,"kind":"sa","stem":"자료를 보세요. 놀이 한마당이 즐거웠던 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["5","5명"],"explanation":["자료에서 「놀이 한마당」을 고른 이름표만 ／ 표시를 하며 세어요.","놀이 한마당이 즐거웠던 학생은 5명이에요.","빠뜨리거나 두 번 세지 않게 센 것에 표시하며 세요."],"asset":{"type":"cards","topic":"act","items":[["서준","현장체험학습"],["민하","텃밭 가꾸기"],["수찬","현장체험학습"],["연우","텃밭 가꾸기"],["다윤","놀이 한마당"],["우영","현장체험학습"],["재이","현장체험학습"],["채원","안전 체험"],["호진","신나는 무용"],["정우","놀이 한마당"],["지아","신나는 무용"],["소민","놀이 한마당"],["세미","안전 체험"],["도현","안전 체험"],["상혁","텃밭 가꾸기"],["슬기","현장체험학습"],["효주","현장체험학습"],["소희","현장체험학습"],["시후","놀이 한마당"],["지은","놀이 한마당"]]},"variant_rule":{"alt":[{"stem":"자료를 보세요. 안전 체험이 즐거웠던 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["자료에서 「안전 체험」을 고른 이름표만 ／ 표시를 하며 세어요.","안전 체험이 즐거웠던 학생은 3명이에요.","빠뜨리거나 두 번 세지 않게 센 것에 표시하며 세요."],"asset":{"type":"cards","topic":"act","items":[["서준","현장체험학습"],["민하","텃밭 가꾸기"],["수찬","현장체험학습"],["연우","텃밭 가꾸기"],["다윤","놀이 한마당"],["우영","현장체험학습"],["재이","현장체험학습"],["채원","안전 체험"],["호진","신나는 무용"],["정우","놀이 한마당"],["지아","신나는 무용"],["소민","놀이 한마당"],["세미","안전 체험"],["도현","안전 체험"],["상혁","텃밭 가꾸기"],["슬기","현장체험학습"],["효주","현장체험학습"],["소희","현장체험학습"],["시후","놀이 한마당"],["지은","놀이 한마당"]]},"answer":["3","3명"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_basic#3','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',1,'mc','auto','알고 있어요 — 도형을 모양에 따라 분류하고 그 수를 세었어요. 원은 몇 개인가요?',ARRAY['M2-2-u5-X02']::text[],true,'{"seq":3,"concept":"M2-2-u5-C1","difficulty":1,"kind":"mc","stem":"알고 있어요 — 도형을 모양에 따라 분류하고 그 수를 세었어요. 원은 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"4개","mis":"M2-2-u5-X02"},{"t":"5개","mis":"M2-2-u5-X02"}],"explanation":["표에서 「원」 칸 아래의 수를 읽어요.","사각형 4개, 원 3개, 삼각형 5개예요.","묻는 모양 이름을 찾고 그 아래 수를 읽어요."],"asset":{"type":"sort_table","crit":"shape","cols":["사각형","원","삼각형"],"counts":[4,3,5],"unit":"개"},"variant_rule":{"alt":[{"stem":"알고 있어요 — 기준을 「색깔 수」로 정하여 과자를 분류했더니 한 가지 색 과자가 4개, 두 가지 색 과자가 6개였어요. 과자는 모두 몇 개인가요?","options":[{"t":"10개","correct":true},{"t":"6개","mis":"M2-2-u5-X03"},{"t":"2개","mis":"M2-2-u5-X04"}],"explanation":["한 가지 색 4개, 두 가지 색 6개예요.","4 + 6 = 10이니 과자는 모두 10개예요.","2는 나눈 칸(가지)의 수, 6은 한 칸의 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_basic#4','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C2',1,'mc','auto','슬기네 반 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X04']::text[],true,'{"seq":4,"concept":"M2-2-u5-C2","difficulty":1,"kind":"mc","stem":"슬기네 반 학생은 모두 몇 명인가요?","options":[{"t":"20명","correct":true},{"t":"7명","mis":"M2-2-u5-X03"},{"t":"5명","mis":"M2-2-u5-X04"}],"explanation":["표의 활동별 수는 현장체험학습 7명, 안전 체험 3명, 놀이 한마당 5명, 신나는 무용 2명, 텃밭 가꾸기 3명이에요.","7 + 3 + 5 + 2 + 3 = 20이니 모두 20명이에요.","항목별 수를 모두 더한 것이 합계 — 전체 수예요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":null},"variant_rule":{"alt":[{"stem":"슬기네 모둠이 가지고 있는 연결 모형은 모두 몇 개인가요?","explanation":["표의 색깔별 수는 주황색 9개, 파란색 10개, 노란색 8개예요.","9 + 10 + 8 = 27이니 모두 27개예요.","항목별 수를 모두 더한 것이 합계 — 전체 수예요."],"asset":{"type":"ftable","topic":"block","title":"슬기네 모둠이 가지고 있는 연결 모형의 색깔별 개수","head":"색깔","cols":["주황색","파란색","노란색"],"counts":[9,10,8],"unit":"개","vh":"연결 모형 수","total":null},"options":[{"t":"27개","correct":true},{"t":"10개","mis":"M2-2-u5-X03"},{"t":"3개","mis":"M2-2-u5-X04"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_basic#5','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',2,'mc','auto','슬기네 반 자료를 기준에 따라 분류하여 학생들의 이름을 쓸 때, 이름을 쓴 이름표에 ／ 표시를 하는 까닭은 무엇인가요?',ARRAY['M2-2-u5-X01','M2-2-u5-X15']::text[],false,'{"seq":5,"concept":"M2-2-u5-C1","difficulty":2,"kind":"mc","stem":"슬기네 반 자료를 기준에 따라 분류하여 학생들의 이름을 쓸 때, 이름을 쓴 이름표에 ／ 표시를 하는 까닭은 무엇인가요?","options":[{"t":"빠뜨리거나 이름을 여러 번 쓰지 않으려고","correct":true},{"t":"표시를 하면 학생 수가 늘어나서","mis":"M2-2-u5-X01"},{"t":"합계를 먼저 쓰려고","mis":"M2-2-u5-X15"}],"explanation":["이름을 쓴 것과 아직 안 쓴 것을 구분하려고 표시해요.","그러면 빠뜨리거나 같은 이름을 두 번 쓰지 않아요.","표시를 해도 학생 수는 그대로예요."],"asset":{"type":"cards","topic":"act","items":[["서준","현장체험학습"],["민하","텃밭 가꾸기"],["수찬","현장체험학습"],["연우","텃밭 가꾸기"],["다윤","놀이 한마당"],["우영","현장체험학습"],["재이","현장체험학습"],["채원","안전 체험"],["호진","신나는 무용"],["정우","놀이 한마당"],["지아","신나는 무용"],["소민","놀이 한마당"],["세미","안전 체험"],["도현","안전 체험"],["상혁","텃밭 가꾸기"],["슬기","현장체험학습"],["효주","현장체험학습"],["소희","현장체험학습"],["시후","놀이 한마당"],["지은","놀이 한마당"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_basic#6','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',2,'match','auto','슬기네 반 자료를 활동별로 분류했어요. 칸에 모인 이름 수를 세어 표의 수와 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u5-C1","difficulty":2,"kind":"match","stem":"슬기네 반 자료를 활동별로 분류했어요. 칸에 모인 이름 수를 세어 표의 수와 이으세요.","pairs":[{"l":"안전 체험 — 채원·세미·도현","r":"3명"},{"l":"신나는 무용 — 호진·지아","r":"2명"},{"l":"놀이 한마당 — 다윤·소민·정우·시후·지은","r":"5명"}],"mis":"M2-2-u5-X01","explanation":["칸에 모인 이름을 하나씩 세요.","안전 체험 3명, 신나는 무용 2명이에요.","놀이 한마당은 5명이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 슬기네 반 자료를 활동별로 분류했어요. 칸에 모인 이름 수를 세어 표의 수와 이으세요.","pairs":[{"l":"현장체험학습 — 슬기·서준·수찬·재이·우영·효주·소희","r":"7명"},{"l":"텃밭 가꾸기 — 민하·연우·상혁","r":"3명"},{"l":"신나는 무용 — 호진·지아","r":"2명"}],"explanation":["칸에 모인 이름을 하나씩 세요.","현장체험학습 7명, 텃밭 가꾸기 3명이에요.","신나는 무용은 2명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_basic#7','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C2',2,'ox','auto','표를 보면 서준이가 어떤 활동을 즐거워했는지 알 수 있어요.',ARRAY['M2-2-u5-X16']::text[],true,'{"seq":7,"concept":"M2-2-u5-C2","difficulty":2,"kind":"ox","stem":"표를 보면 서준이가 어떤 활동을 즐거워했는지 알 수 있어요.","answer":"X","reason_options":[{"t":"표에는 활동별 학생 수만 있고 누가 골랐는지는 없으니까","correct":true},{"t":"표에는 조사한 것이 다 적혀 있으니까","mis":"M2-2-u5-X16"}],"mis":"M2-2-u5-X16","explanation":["표에는 활동별 학생 수와 합계만 적혀 있어요.","누가 무엇을 골랐는지는 자료(이름표)를 봐야 알아요.","표는 활동별 학생 수를 한눈에 알기 좋아요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20},"variant_rule":{"alt":[{"stem":"표를 보면 활동별 학생 수를 한눈에 알 수 있어요.","answer":"O","reason_options":[{"t":"활동마다 학생 수가 수로 적혀 있으니까","correct":true},{"t":"이름이 하나씩 다 적혀 있으니까","mis":"M2-2-u5-X16"}],"explanation":["표에는 활동별 학생 수가 수로 적혀 있어요.","그래서 몇 명인지 바로 읽을 수 있어요.","이름은 자료에만 있어요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_basic#8','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C2',2,'sa','auto','표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u5-C2","difficulty":2,"kind":"sa","stem":"표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["나머지 칸을 더하면 7 + 3 + 2 + 3 = 15예요.","15 + □ = 20이니 □ = 5예요.","합계에서 나머지 칸의 수를 빼면 빈칸의 수예요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,null,2,3],"unit":"명","vh":"학생 수","total":20},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["나머지 칸을 더하면 9 + 8 = 17이에요.","17 + □ = 27이니 □ = 10이에요.","합계에서 나머지 칸의 수를 빼면 빈칸의 수예요."],"asset":{"type":"ftable","topic":"block","title":"슬기네 모둠이 가지고 있는 연결 모형의 색깔별 개수","head":"색깔","cols":["주황색","파란색","노란색"],"counts":[9,null,8],"unit":"개","vh":"연결 모형 수","total":27},"answer":["10"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_basic#9','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',2,'mc','auto','『수학익힘』 단추 문제예요. 구멍 수에 따라 분류했더니 구멍이 2개인 단추 5개, 3개인 단추 1개, 4개인 단추 6개였어요. 구멍이 4개인 단추는 구멍이 2개인 단추보다 어떤가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],true,'{"seq":9,"concept":"M2-2-u5-C1","difficulty":2,"kind":"mc","stem":"『수학익힘』 단추 문제예요. 구멍 수에 따라 분류했더니 구멍이 2개인 단추 5개, 3개인 단추 1개, 4개인 단추 6개였어요. 구멍이 4개인 단추는 구멍이 2개인 단추보다 어떤가요?","options":[{"t":"많습니다","correct":true},{"t":"적습니다","mis":"M2-2-u5-X09"},{"t":"같습니다","mis":"M2-2-u5-X07"}],"explanation":["구멍이 4개인 단추는 6개, 2개인 단추는 5개예요.","6은 5보다 크니 4개인 단추가 더 많아요.","구멍 수 4가 2보다 커서가 아니라 단추 수 6과 5를 견주어요."],"variant_rule":{"alt":[{"stem":"『수학익힘』 단추 문제예요. 모양에 따라 분류했더니 ◯ 모양 단추 5개, △ 모양 단추 3개, □ 모양 단추 4개였어요. □ 모양 단추는 ◯ 모양 단추보다 어떤가요?","options":[{"t":"적습니다","correct":true},{"t":"많습니다","mis":"M2-2-u5-X09"},{"t":"같습니다","mis":"M2-2-u5-X07"}],"explanation":["□ 모양 단추는 4개, ◯ 모양 단추는 5개예요.","4는 5보다 작으니 □ 모양 단추가 더 적어요.","세어 놓은 수끼리 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_basic#10','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C2',3,'error','auto','슬기네 반 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X16']::text[],true,'{"seq":10,"concept":"M2-2-u5-C2","difficulty":3,"kind":"error","stem":"슬기네 반 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수찬 — 「합계가 20이니까 현장체험학습이 즐거웠던 학생이 20명이야.」","correct":true,"mis_target":"M2-2-u5-X03"},{"t":"지아 — 「활동별 학생 수를 한눈에 알 수 있어.」","mis":"M2-2-u5-X16"},{"t":"연우 — 「7 + 3 + 5 + 2 + 3 = 20이니까 합계는 20이야.」","mis":"M2-2-u5-X16"}],"explanation":["합계 20은 모든 활동의 학생 수를 더한 수예요.","현장체험학습이 즐거웠던 학생은 7명이에요.","수찬이는 합계를 한 활동의 수로 읽었어요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 슬기네 반 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「가장 큰 수가 7이니까 슬기네 반은 7명이야.」","correct":true,"mis_target":"M2-2-u5-X03"},{"t":"서아 — 「놀이 한마당이 즐거웠던 학생은 5명이야.」","mis":"M2-2-u5-X16"},{"t":"민수 — 「합계 20이 슬기네 반 학생 수야.」","mis":"M2-2-u5-X16"}],"explanation":["슬기네 반 학생 수는 합계 20명이에요.","7은 현장체험학습 한 칸의 수예요.","하람이는 한 칸의 수를 전체로 읽었어요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_challenge#1','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C1',2,'sa','auto','파란색 연결 모형은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u5-C1","difficulty":2,"kind":"sa","stem":"파란색 연결 모형은 몇 개인가요? 숫자로 쓰세요.","answer":["10","10개"],"explanation":["표에서 「파란색」 칸 아래의 수를 읽어요.","파란색 연결 모형은 10개예요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"asset":{"type":"ftable","topic":"block","title":"슬기네 모둠이 가지고 있는 연결 모형의 색깔별 개수","head":"색깔","cols":["주황색","파란색","노란색"],"counts":[9,10,8],"unit":"개","vh":"연결 모형 수","total":27},"variant_rule":{"alt":[{"stem":"주황색 연결 모형은 몇 개인가요? 숫자로 쓰세요.","explanation":["표에서 「주황색」 칸 아래의 수를 읽어요.","주황색 연결 모형은 9개예요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"asset":{"type":"ftable","topic":"block","title":"슬기네 모둠이 가지고 있는 연결 모형의 색깔별 개수","head":"색깔","cols":["주황색","파란색","노란색"],"counts":[9,10,8],"unit":"개","vh":"연결 모형 수","total":27},"answer":["9","9개"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_challenge#2','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',2,'blank','auto','『수학익힘』에서 슬기네 모둠이 가지고 있는 연결 모형 수를 표로 나타내고 이야기를 완성했어요. 「연결 모형은 표로 나타내면 색깔별 연결 모형 수를 쉽게 알 수 있어. 연결 모형은 모두 ( )개야.」 ( )에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X04']::text[],false,'{"seq":2,"concept":"M2-2-u5-C2","difficulty":2,"kind":"blank","stem":"『수학익힘』에서 슬기네 모둠이 가지고 있는 연결 모형 수를 표로 나타내고 이야기를 완성했어요. 「연결 모형은 표로 나타내면 색깔별 연결 모형 수를 쉽게 알 수 있어. 연결 모형은 모두 ( )개야.」 ( )에 알맞은 수는 얼마인가요?","options":[{"t":"27","correct":true},{"t":"10","mis":"M2-2-u5-X03"},{"t":"3","mis":"M2-2-u5-X04"}],"explanation":["주황색 9개, 파란색 10개, 노란색 8개예요.","9 + 10 + 8 = 27이니 모두 27개예요.","10은 파란색 한 칸, 3은 색깔 가짓수예요."],"asset":{"type":"ftable","topic":"block","title":"슬기네 모둠이 가지고 있는 연결 모형의 색깔별 개수","head":"색깔","cols":["주황색","파란색","노란색"],"counts":[9,10,8],"unit":"개","vh":"연결 모형 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
