INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_challenge#4','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',3,'mc','auto','현장체험학습이 아닌 활동을 즐거워한 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X03','M2-2-u5-X01']::text[],false,'{"seq":4,"concept":"M2-2-u5-C2","difficulty":3,"kind":"mc","stem":"현장체험학습이 아닌 활동을 즐거워한 학생은 모두 몇 명인가요?","options":[{"t":"13명","correct":true},{"t":"7명","mis":"M2-2-u5-X09"},{"t":"20명","mis":"M2-2-u5-X03"},{"t":"12명","mis":"M2-2-u5-X01"}],"explanation":["현장체험학습이 아닌 활동은 안전 체험·놀이 한마당·신나는 무용·텃밭 가꾸기예요.","3 + 5 + 2 + 3 = 13이에요.","합계 20에서 현장체험학습 7을 빼도 13이에요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_challenge#5','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',3,'mc','auto','슬기가 「많은 학생들이 즐거워했던 활동은 내년에도 하면 좋겠어.」라고 말했어요. 표를 보고 내년에도 하면 좋을 활동을 고르면 어느 것인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],false,'{"seq":5,"concept":"M2-2-u5-C2","difficulty":3,"kind":"mc","stem":"슬기가 「많은 학생들이 즐거워했던 활동은 내년에도 하면 좋겠어.」라고 말했어요. 표를 보고 내년에도 하면 좋을 활동을 고르면 어느 것인가요?","options":[{"t":"현장체험학습","correct":true},{"t":"신나는 무용","mis":"M2-2-u5-X09"},{"t":"텃밭 가꾸기","mis":"M2-2-u5-X07"},{"t":"놀이 한마당","mis":"M2-2-u5-X07"}],"explanation":["가장 많은 학생들이 즐거워했던 활동을 찾아요.","현장체험학습이 7명으로 가장 많아요.","표의 맨 끝 칸이나 두 번째로 많은 칸이 아니라 수가 가장 큰 칸이에요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_challenge#6','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C1',3,'ox','auto','자료를 분류한 항목과 표의 항목은 같아요.',ARRAY['M2-2-u5-X15']::text[],false,'{"seq":6,"concept":"M2-2-u5-C1","difficulty":3,"kind":"ox","stem":"자료를 분류한 항목과 표의 항목은 같아요.","answer":"O","reason_options":[{"t":"분류한 칸의 이름을 그대로 쓰고 칸마다 센 수를 표에 적으니까","correct":true},{"t":"표를 만들 때는 항목을 새로 정하니까","mis":"M2-2-u5-X15"}],"mis":"M2-2-u5-X15","explanation":["분류한 칸의 이름이 곧 표의 항목이에요.","칸마다 이름 수를 세어 표에 수로 적어요.","그래서 분류 항목과 표의 항목은 같아요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_challenge#7','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',3,'error','auto','자료, 분류한 것, 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X16']::text[],false,'{"seq":7,"concept":"M2-2-u5-C2","difficulty":3,"kind":"error","stem":"자료, 분류한 것, 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「표를 보면 신나는 무용을 즐거워한 학생이 누구누구인지 알 수 있어.」","correct":true,"mis_target":"M2-2-u5-X16"},{"t":"소율 — 「분류한 것을 보면 신나는 무용을 즐거워한 학생이 호진이와 지아인 것을 알 수 있어.」","mis":"M2-2-u5-X16"},{"t":"예준 — 「표를 보면 활동별 학생 수를 한눈에 알 수 있어.」","mis":"M2-2-u5-X16"}],"explanation":["자료는 한 사람 한 사람이 무엇을 즐거워했는지, 분류한 것은 활동별로 누구인지 알려 줘요.","표에는 이름 대신 수만 있어요.","그래서 표로는 누구인지 알 수 없어요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_challenge#8','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',4,'essay','teacher','슬기네 반 표의 합계 20은 어떻게 구한 수인지 설명하고, 합계가 무엇을 뜻하는지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u5-C2","difficulty":4,"kind":"essay","stem":"슬기네 반 표의 합계 20은 어떻게 구한 수인지 설명하고, 합계가 무엇을 뜻하는지 써 보세요.","answer_guide":{"answer":"예: 활동별 학생 수 7, 3, 5, 2, 3을 모두 더해서 7 + 3 + 5 + 2 + 3 = 20으로 구했다. 합계는 조사한 학생 전체의 수, 곧 슬기네 반 학생 수이다.","scoring_points":["항목별 수를 모두 더했음을 썼는가","7 + 3 + 5 + 2 + 3 = 20을 썼는가","합계가 전체 학생 수임을 썼는가"]},"explanation":["교과서 말풍선처럼 활동별 학생 수를 모두 더해서 합계에 써요.","7 + 3 + 5 + 2 + 3 = 20이에요.","합계 20명이 슬기네 반 전체 학생 수예요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_challenge#9','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C1',4,'essay','teacher','이름표를 하나하나 분류하지 않고 자료를 보면서 바로 표로 나타내려고 해요. 빠뜨리거나 두 번 세지 않으려면 어떻게 세면 좋을지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u5-C1","difficulty":4,"kind":"essay","stem":"이름표를 하나하나 분류하지 않고 자료를 보면서 바로 표로 나타내려고 해요. 빠뜨리거나 두 번 세지 않으려면 어떻게 세면 좋을지 설명해 보세요.","answer_guide":{"answer":"예: 활동마다 세면서 표시하기 칸에 ／(또는 正)를 하나씩 긋고, 센 이름표에도 ／ 표시를 해 둔다. 다 세면 표시를 세어 수로 적고, 수를 모두 더한 합계가 20인지 확인한다.","scoring_points":["세면서 표시하기(／ 또는 正)를 썼는가","센 자료에 표시해 두는 것을 썼는가","합계가 전체 수와 같은지 확인함을 썼는가"]},"explanation":["분류하지 않아도 세면서 표시하기로 바로 표를 만들 수 있어요.","센 이름표에 ／ 표시를 하면 빠뜨리거나 두 번 세지 않아요.","다 세고 합계가 20인지 확인해요."],"asset":{"type":"cards","topic":"act","items":[["서준","현장체험학습"],["민하","텃밭 가꾸기"],["수찬","현장체험학습"],["연우","텃밭 가꾸기"],["다윤","놀이 한마당"],["우영","현장체험학습"],["재이","현장체험학습"],["채원","안전 체험"],["호진","신나는 무용"],["정우","놀이 한마당"],["지아","신나는 무용"],["소민","놀이 한마당"],["세미","안전 체험"],["도현","안전 체험"],["상혁","텃밭 가꾸기"],["슬기","현장체험학습"],["효주","현장체험학습"],["소희","현장체험학습"],["시후","놀이 한마당"],["지은","놀이 한마당"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L02_challenge#10','math',2,2,'u5','L02','tb_g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',4,'essay','teacher','자료를 그대로 둘 때보다 표로 나타내면 좋은 점을 한 가지 쓰고, 자료에서만 알 수 있는 것도 한 가지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u5-C2","difficulty":4,"kind":"essay","stem":"자료를 그대로 둘 때보다 표로 나타내면 좋은 점을 한 가지 쓰고, 자료에서만 알 수 있는 것도 한 가지 써 보세요.","answer_guide":{"answer":"예: 표로 나타내면 활동별 학생 수를 한눈에 알 수 있고 합계도 바로 알 수 있다. 자료에서는 누가 어떤 활동을 즐거워했는지 알 수 있다.","scoring_points":["표의 좋은 점(활동별 수·합계를 한눈에)을 썼는가","자료에서만 알 수 있는 것(누가 무엇을 골랐는지)을 썼는가","둘을 구분해서 썼는가"]},"explanation":["표는 활동별 학생 수와 합계를 한눈에 보여 줘요.","자료는 누가 무엇을 즐거워했는지 보여 줘요.","표와 자료는 알기 좋은 것이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_basic#1','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C3',1,'mc','auto','우리 반 친구들이 태어난 계절을 조사하려고 해요. 교과서에 나온 조사 방법이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u5-X09']::text[],true,'{"seq":1,"concept":"M2-2-u5-C3","difficulty":1,"kind":"mc","stem":"우리 반 친구들이 태어난 계절을 조사하려고 해요. 교과서에 나온 조사 방법이 아닌 것은 어느 것인가요?","options":[{"t":"내가 생각나는 대로 계절을 적는다","correct":true},{"t":"계절별로 손을 든다","mis":"M2-2-u5-X09"},{"t":"태어난 계절에 이름을 써서 붙인다","mis":"M2-2-u5-X09"}],"explanation":["교과서에는 계절별로 손 들기, 한 사람씩 말하기, 이름을 써서 붙이기, 이름과 태어난 계절을 써서 붙이기가 나와요.","생각나는 대로 적으면 친구들을 조사한 것이 아니에요.","「아닌 것」을 묻는지 다시 읽어요."],"variant_rule":{"alt":[{"stem":"조사하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친한 친구에게만 물어본다","correct":true},{"t":"한 사람씩 차례로 말한다","mis":"M2-2-u5-X15"},{"t":"이름과 태어난 계절을 써서 붙인다","mis":"M2-2-u5-X15"}],"explanation":["조사는 반 친구 모두에게 해야 해요.","한 사람씩 말하거나 이름을 써서 붙이면 모두 조사할 수 있어요.","몇 명만 고르면 빠진 친구가 생겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_basic#2','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C3',1,'match','auto','태어난 달을 보고 알맞은 계절과 이으세요. (봄 3, 4, 5월 · 여름 6, 7, 8월 · 가을 9, 10, 11월 · 겨울 12, 1, 2월)','{}'::text[],true,'{"seq":2,"concept":"M2-2-u5-C3","difficulty":1,"kind":"match","stem":"태어난 달을 보고 알맞은 계절과 이으세요. (봄 3, 4, 5월 · 여름 6, 7, 8월 · 가을 9, 10, 11월 · 겨울 12, 1, 2월)","pairs":[{"l":"4월","r":"봄"},{"l":"7월","r":"여름"},{"l":"1월","r":"겨울"}],"mis":"M2-2-u5-X02","explanation":["3, 4, 5월은 봄, 6, 7, 8월은 여름이에요.","9, 10, 11월은 가을이에요.","12, 1, 2월은 겨울이에요 — 1월도 겨울이에요."],"variant_rule":{"alt":[{"stem":"칠판의 「생일 축하해요」를 보고 친구가 태어난 계절과 이으세요. (봄 3, 4, 5월 · 여름 6, 7, 8월 · 가을 9, 10, 11월 · 겨울 12, 1, 2월)","pairs":[{"l":"호진 — 1월","r":"겨울"},{"l":"재이 — 5월","r":"봄"},{"l":"슬기 — 8월","r":"여름"}],"explanation":["1월은 12, 1, 2월에 들어가니 겨울이에요.","5월은 봄, 8월은 여름이에요.","달이 어느 묶음에 있는지 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_basic#3','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',1,'sa','auto','가을에 태어난 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u5-C4","difficulty":1,"kind":"sa","stem":"가을에 태어난 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["6","6명"],"explanation":["표에서 「가을」 칸 아래의 수를 읽어요.","가을에 태어난 학생은 6명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20},"variant_rule":{"alt":[{"stem":"여름에 태어난 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["표에서 「여름」 칸 아래의 수를 읽어요.","여름에 태어난 학생은 4명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20},"answer":["4","4명"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_basic#4','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',1,'mc','auto','세미네 반 친구들이 태어난 계절을 조사한 표에 「제목을 써 볼까?」 하고 제목을 붙이려고 해요. 알맞은 제목은 어느 것인가요?',ARRAY['M2-2-u5-X15','M2-2-u5-X03']::text[],false,'{"seq":4,"concept":"M2-2-u5-C4","difficulty":1,"kind":"mc","stem":"세미네 반 친구들이 태어난 계절을 조사한 표에 「제목을 써 볼까?」 하고 제목을 붙이려고 해요. 알맞은 제목은 어느 것인가요?","options":[{"t":"우리 반 친구들이 태어난 계절별 학생 수","correct":true},{"t":"봄, 여름, 가을, 겨울","mis":"M2-2-u5-X15"},{"t":"합계 20명","mis":"M2-2-u5-X03"}],"explanation":["제목은 무엇을 조사해 나타낸 표인지 알려 줘요.","태어난 계절별로 학생 수를 나타냈으니 「우리 반 친구들이 태어난 계절별 학생 수」예요.","계절 이름은 항목, 20은 합계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_basic#5','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',2,'sa','auto','표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u5-C4","difficulty":2,"kind":"sa","stem":"표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나머지 칸을 더하면 7 + 6 + 3 = 16이에요.","16 + □ = 20이니 □ = 4예요.","합계에서 나머지 칸의 수를 빼면 빈칸의 수예요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,null,6,3],"unit":"명","vh":"학생 수","total":20},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["나머지 칸을 더하면 7 + 4 + 6 = 17이에요.","17 + □ = 20이니 □ = 3이에요.","합계에서 나머지 칸의 수를 빼면 빈칸의 수예요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,null],"unit":"명","vh":"학생 수","total":20},"answer":["3"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_basic#6','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',2,'mc','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u5-X06','M2-2-u5-X01']::text[],true,'{"seq":6,"concept":"M2-2-u5-C4","difficulty":2,"kind":"mc","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"7","correct":true},{"t":"6","mis":"M2-2-u5-X06"},{"t":"8","mis":"M2-2-u5-X01"}],"explanation":["「봄」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／／ → 7","그래서 빈칸은 7이에요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[null,4,6,3],"unit":"명","vh":"학생 수","tally":[7,4,6,3]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. ／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요?","explanation":["「가을」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／ → 6","그래서 빈칸은 6이에요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,null,3],"unit":"명","vh":"학생 수","tally":[7,4,6,3]},"options":[{"t":"6","correct":true},{"t":"5","mis":"M2-2-u5-X06"},{"t":"7","mis":"M2-2-u5-X01"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_basic#7','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C3',2,'ox','auto','조사하는 방법은 무엇을 조사하느냐에 따라 알맞은 것이 달라요.',ARRAY['M2-2-u5-X15']::text[],false,'{"seq":7,"concept":"M2-2-u5-C3","difficulty":2,"kind":"ox","stem":"조사하는 방법은 무엇을 조사하느냐에 따라 알맞은 것이 달라요.","answer":"O","reason_options":[{"t":"말하기·손 들기·이름 붙이기 가운데 조사할 것에 맞는 방법을 고르니까","correct":true},{"t":"조사 방법은 언제나 한 가지뿐이니까","mis":"M2-2-u5-X15"}],"mis":"M2-2-u5-X15","explanation":["조사 방법에는 묻고 답하기, 쓰기, 이동하기 등이 있어요.","무엇을 조사하느냐에 따라 알맞은 방법이 달라요.","어떤 방법이든 빠진 친구가 없어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_basic#8','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C3',2,'mc','auto','교실을 봄·여름·가을·겨울 구역으로 나누고 친구들이 자기가 태어난 계절 구역으로 가서 서게 했어요. 이 조사 방법에서 꼭 지켜야 할 것은 무엇인가요?',ARRAY['M2-2-u5-X01','M2-2-u5-X15']::text[],false,'{"seq":8,"concept":"M2-2-u5-C3","difficulty":2,"kind":"mc","stem":"교실을 봄·여름·가을·겨울 구역으로 나누고 친구들이 자기가 태어난 계절 구역으로 가서 서게 했어요. 이 조사 방법에서 꼭 지켜야 할 것은 무엇인가요?","options":[{"t":"모든 친구가 한 구역에만 서고 구역마다 사람 수를 센다","correct":true},{"t":"한 친구가 두 구역에 서도 된다","mis":"M2-2-u5-X01"},{"t":"사람이 많은 구역만 센다","mis":"M2-2-u5-X15"}],"explanation":["구역을 나누어 이동하기도 조사 방법이에요.","한 친구는 한 구역에만 서야 두 번 세지 않아요.","모든 구역의 사람 수를 세어야 빠진 친구가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_basic#9','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',2,'mc','auto','자료를 보세요. 겨울에 태어난 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01']::text[],true,'{"seq":9,"concept":"M2-2-u5-C4","difficulty":2,"kind":"mc","stem":"자료를 보세요. 겨울에 태어난 학생은 몇 명인가요?","options":[{"t":"3명","correct":true},{"t":"4명","mis":"M2-2-u5-X01"},{"t":"2명","mis":"M2-2-u5-X01"}],"explanation":["자료에서 「겨울」을 고른 이름표만 ／ 표시를 하며 세어요.","겨울에 태어난 학생은 3명이에요.","빠뜨리거나 두 번 세지 않게 센 것에 표시하며 세요."],"asset":{"type":"cards","topic":"season","items":[["지아","봄"],["재이","봄"],["연우","봄"],["슬기","봄"],["수찬","봄"],["소희","봄"],["세미","봄"],["민하","여름"],["우영","여름"],["시후","여름"],["채원","여름"],["지은","가을"],["상혁","가을"],["호진","가을"],["효주","가을"],["서준","가을"],["정우","가을"],["도현","겨울"],["소민","겨울"],["다윤","겨울"]]},"variant_rule":{"alt":[{"stem":"자료를 보세요. 여름에 태어난 학생은 몇 명인가요?","explanation":["자료에서 「여름」을 고른 이름표만 ／ 표시를 하며 세어요.","여름에 태어난 학생은 4명이에요.","빠뜨리거나 두 번 세지 않게 센 것에 표시하며 세요."],"asset":{"type":"cards","topic":"season","items":[["지아","봄"],["재이","봄"],["연우","봄"],["슬기","봄"],["수찬","봄"],["소희","봄"],["세미","봄"],["민하","여름"],["우영","여름"],["시후","여름"],["채원","여름"],["지은","가을"],["상혁","가을"],["호진","가을"],["효주","가을"],["서준","가을"],["정우","가을"],["도현","겨울"],["소민","겨울"],["다윤","겨울"]]},"options":[{"t":"4명","correct":true},{"t":"5명","mis":"M2-2-u5-X01"},{"t":"3명","mis":"M2-2-u5-X01"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_basic#10','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',3,'error','auto','태어난 계절을 조사해 표를 만들었어요. 잘못 만든 친구는 누구인가요?',ARRAY['M2-2-u5-X15']::text[],true,'{"seq":10,"concept":"M2-2-u5-C4","difficulty":3,"kind":"error","stem":"태어난 계절을 조사해 표를 만들었어요. 잘못 만든 친구는 누구인가요?","options":[{"t":"윤슬 — 조사한 친구가 적어서 합계를 25로 늘려 적었다","correct":true,"mis_target":"M2-2-u5-X15"},{"t":"가은 — 제목을 「우리 반 친구들이 태어난 계절별 학생 수」라고 썼다","mis":"M2-2-u5-X15"},{"t":"태오 — 7 + 4 + 6 + 3을 더해 합계 20을 썼다","mis":"M2-2-u5-X15"}],"explanation":["합계는 항목별 수를 더한 그대로 적어요.","마음대로 늘려 쓰면 조사한 것이 아니에요.","제목을 쓰고 더해서 합계를 쓴 것은 바르게 만든 거예요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 태어난 계절을 조사해 표를 만들었어요. 잘못 만든 친구는 누구인가요?","options":[{"t":"도윤 — 제목 없이 수만 적었다","correct":true,"mis_target":"M2-2-u5-X15"},{"t":"나린 — 계절 칸을 봄·여름·가을·겨울로 나누어 적었다","mis":"M2-2-u5-X15"},{"t":"서아 — 합계 칸에 20을 적었다","mis":"M2-2-u5-X15"}],"explanation":["표에는 무엇을 조사한 것인지 제목을 써야 해요.","칸을 나누고 합계를 쓴 것은 바르게 만든 거예요.","제목·항목·수·합계를 다 갖추어요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_challenge#1','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C4',2,'mc','auto','칠판의 「생일 축하해요」에는 1월 호진·소민, 3월 지아, 5월 재이, 6월 연우, 8월 슬기·시후, 10월 소희·지은·수찬, 11월 정우, 12월 세미가 적혀 있어요. 가을(9, 10, 11월)에 생일인 친구는 몇 명인가요?',ARRAY['M2-2-u5-X01','M2-2-u5-X02','M2-2-u5-X03']::text[],true,'{"seq":1,"concept":"M2-2-u5-C4","difficulty":2,"kind":"mc","stem":"칠판의 「생일 축하해요」에는 1월 호진·소민, 3월 지아, 5월 재이, 6월 연우, 8월 슬기·시후, 10월 소희·지은·수찬, 11월 정우, 12월 세미가 적혀 있어요. 가을(9, 10, 11월)에 생일인 친구는 몇 명인가요?","options":[{"t":"4명","correct":true},{"t":"3명","mis":"M2-2-u5-X01"},{"t":"5명","mis":"M2-2-u5-X02"},{"t":"12명","mis":"M2-2-u5-X03"}],"explanation":["가을은 9, 10, 11월이에요.","10월 소희·지은·수찬, 11월 정우 — 모두 4명이에요.","11월 정우를 빠뜨리거나 8월 친구를 넣지 않아요."],"variant_rule":{"alt":[{"stem":"칠판의 「생일 축하해요」에는 1월 호진·소민, 3월 지아, 5월 재이, 6월 연우, 8월 슬기·시후, 10월 소희·지은·수찬, 11월 정우, 12월 세미가 적혀 있어요. 겨울(12, 1, 2월)에 생일인 친구는 몇 명인가요?","options":[{"t":"3명","correct":true},{"t":"1명","mis":"M2-2-u5-X01"},{"t":"2명","mis":"M2-2-u5-X01"},{"t":"12명","mis":"M2-2-u5-X03"}],"explanation":["겨울은 12, 1, 2월이에요.","12월 세미, 1월 호진·소민 — 모두 3명이에요.","1월도 겨울이라는 것을 잊지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_challenge#2','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C4',2,'sa','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M2-2-u5-C4","difficulty":2,"kind":"sa","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["「가을」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／ → 6","그래서 빈칸은 6이에요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,null,3],"unit":"명","vh":"학생 수","tally":[7,4,6,3]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_challenge#3','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C4',3,'mc','auto','『수학익힘』에서 붙임딱지 다섯 가지 모양 조각으로 원하는 모양을 만들고, 사용한 조각 수를 표로 나타냈어요. 조각 수는 차례로 4개, 6개, 7개, 1개, 2개예요. 표의 합계 칸에 쓸 수는 얼마인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X04','M2-2-u5-X01']::text[],false,'{"seq":3,"concept":"M2-2-u5-C4","difficulty":3,"kind":"mc","stem":"『수학익힘』에서 붙임딱지 다섯 가지 모양 조각으로 원하는 모양을 만들고, 사용한 조각 수를 표로 나타냈어요. 조각 수는 차례로 4개, 6개, 7개, 1개, 2개예요. 표의 합계 칸에 쓸 수는 얼마인가요?","options":[{"t":"20","correct":true},{"t":"7","mis":"M2-2-u5-X03"},{"t":"5","mis":"M2-2-u5-X04"},{"t":"19","mis":"M2-2-u5-X01"}],"explanation":["조각별 수는 4, 6, 7, 1, 2예요.","4 + 6 + 7 + 1 + 2 = 20이에요.","7은 가장 많이 사용한 조각 수, 5는 조각 가짓수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_challenge#4','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C3',3,'mc','auto','한 사람씩 차례로 말하기로 조사하면 좋은 점은 무엇인가요?',ARRAY['M2-2-u5-X15','M2-2-u5-X01']::text[],false,'{"seq":4,"concept":"M2-2-u5-C3","difficulty":3,"kind":"mc","stem":"한 사람씩 차례로 말하기로 조사하면 좋은 점은 무엇인가요?","options":[{"t":"차례가 분명해서 빠뜨리기 어렵다","correct":true},{"t":"손을 들지 않아도 되니 빨리 끝난다","mis":"M2-2-u5-X15"},{"t":"말한 친구만 표에 넣어도 된다","mis":"M2-2-u5-X15"},{"t":"이름을 적지 않아도 된다","mis":"M2-2-u5-X01"}],"explanation":["한 사람씩 말하면 누가 말했고 안 했는지 분명해요.","그래서 빠뜨리기 어려워요.","말한 친구의 이름을 계절 칸에 적어 두면 더 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_challenge#5','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C4',3,'sa','auto','봄에 태어난 학생은 겨울에 태어난 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u5-C4","difficulty":3,"kind":"sa","stem":"봄에 태어난 학생은 겨울에 태어난 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["4","4명"],"explanation":["봄에 태어난 학생은 7명, 겨울에 태어난 학생은 3명이에요.","7 − 3 = 4이니 4명 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20},"variant_rule":{"alt":[{"stem":"가을에 태어난 학생은 여름에 태어난 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","explanation":["가을에 태어난 학생은 6명, 여름에 태어난 학생은 4명이에요.","6 − 4 = 2이니 2명 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20},"answer":["2","2명"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_challenge#6','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C4',3,'ox','auto','우리 반은 20명인데 표의 합계가 19이면 어딘가를 빠뜨리거나 잘못 센 거예요.',ARRAY['M2-2-u5-X01']::text[],false,'{"seq":6,"concept":"M2-2-u5-C4","difficulty":3,"kind":"ox","stem":"우리 반은 20명인데 표의 합계가 19이면 어딘가를 빠뜨리거나 잘못 센 거예요.","answer":"O","reason_options":[{"t":"합계는 조사한 전체 수라 반 학생 수와 같아야 하니까","correct":true},{"t":"합계는 반 학생 수와 상관없으니까","mis":"M2-2-u5-X01"}],"mis":"M2-2-u5-X01","explanation":["합계는 조사한 모든 친구의 수예요.","반 전체를 조사했으면 합계는 반 학생 수와 같아야 해요.","다르면 빠뜨리거나 잘못 센 거니 다시 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_challenge#7','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C3',3,'error','auto','조사 방법을 정하는 친구들의 말 가운데 잘못된 것은 무엇인가요?',ARRAY['M2-2-u5-X15']::text[],false,'{"seq":7,"concept":"M2-2-u5-C3","difficulty":3,"kind":"error","stem":"조사 방법을 정하는 친구들의 말 가운데 잘못된 것은 무엇인가요?","options":[{"t":"도윤 — 「내가 좋아하는 친구들에게만 물어보면 돼.」","correct":true,"mis_target":"M2-2-u5-X15"},{"t":"나린 — 「계절별로 손을 들게 하고 세어도 돼.」","mis":"M2-2-u5-X15"},{"t":"서아 — 「이름과 태어난 계절을 써서 붙여도 돼.」","mis":"M2-2-u5-X15"}],"explanation":["조사는 반 친구 모두에게 해야 해요.","손 들기, 이름 써서 붙이기는 모두 교과서에 나온 방법이에요.","몇 명에게만 물으면 빠진 친구가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_challenge#8','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C4',4,'essay','teacher','조사한 자료를 표로 나타낼 때 생각해야 할 점을 교과서 그림 속 말풍선처럼 두 가지 쓰고, 합계가 필요한 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u5-C4","difficulty":4,"kind":"essay","stem":"조사한 자료를 표로 나타낼 때 생각해야 할 점을 교과서 그림 속 말풍선처럼 두 가지 쓰고, 합계가 필요한 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 제목을 써야 하고, 계절에 맞게 칸을 나누어야 한다. 합계는 조사한 전체 학생 수라서 우리 반 학생 수와 같은지 보고 빠진 친구가 없는지 확인할 수 있다.","scoring_points":["제목·칸 나누기·전체 학생 수 가운데 두 가지를 썼는가","합계가 전체 수임을 썼는가","합계로 빠짐을 확인할 수 있음을 썼는가"]},"explanation":["표에는 제목을 쓰고 칸을 알맞게 나누어요.","합계는 조사한 전체 수예요.","합계가 반 학생 수와 같으면 빠뜨린 친구가 없는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_challenge#9','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C3',4,'essay','teacher','태어난 계절을 조사할 때 「계절별로 손 들기」와 「태어난 계절에 이름을 써서 붙이기」 가운데 하나를 고르고, 그 방법의 좋은 점과 조심할 점을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u5-C3","difficulty":4,"kind":"essay","stem":"태어난 계절을 조사할 때 「계절별로 손 들기」와 「태어난 계절에 이름을 써서 붙이기」 가운데 하나를 고르고, 그 방법의 좋은 점과 조심할 점을 설명해 보세요.","answer_guide":{"answer":"예: 이름을 써서 붙이기를 고르면 누가 어느 계절인지 남아서 나중에 다시 셀 수 있다. 다만 한 사람이 두 번 붙이거나 안 붙인 친구가 없도록 붙인 이름 수가 반 학생 수와 같은지 확인해야 한다.","scoring_points":["방법을 하나 골랐는가","좋은 점을 썼는가","빠짐·두 번 세기를 막는 조심할 점을 썼는가"]},"explanation":["손 들기는 빠르고, 이름 붙이기는 누가 어느 계절인지 남아요.","어느 방법이든 좋은 점이 있어요.","빠진 친구가 없게 합계로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L03_challenge#10','math',2,2,'u5','L03','tb_g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C4',4,'mc','auto','세미네 반 표를 보고 알 수 있는 내용을 바르게 말한 것은 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X08','M2-2-u5-X04']::text[],false,'{"seq":10,"concept":"M2-2-u5-C4","difficulty":4,"kind":"mc","stem":"세미네 반 표를 보고 알 수 있는 내용을 바르게 말한 것은 무엇인가요?","options":[{"t":"가장 많은 학생들이 태어난 계절은 봄이고, 가장 적은 학생들이 태어난 계절은 겨울이에요","correct":true},{"t":"봄에 태어난 학생이 여름에 태어난 학생보다 적어요","mis":"M2-2-u5-X09"},{"t":"여름과 겨울에 태어난 학생은 모두 6명이에요","mis":"M2-2-u5-X08"},{"t":"우리 반 학생은 모두 4명이에요","mis":"M2-2-u5-X04"}],"explanation":["봄 7명이 가장 많고 겨울 3명이 가장 적어요.","여름 4 + 겨울 3 = 7명이에요.","4는 계절 가짓수이고 반 학생 수는 합계 20명이에요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_basic#1','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C6',1,'mc','auto','자료를 보세요. 개를 좋아하는 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01']::text[],true,'{"seq":1,"concept":"M2-2-u5-C6","difficulty":1,"kind":"mc","stem":"자료를 보세요. 개를 좋아하는 학생은 몇 명인가요?","options":[{"t":"6명","correct":true},{"t":"7명","mis":"M2-2-u5-X01"},{"t":"5명","mis":"M2-2-u5-X01"}],"explanation":["자료에서 「개」를 고른 이름표만 ／ 표시를 하며 세어요.","개를 좋아하는 학생은 6명이에요.","빠뜨리거나 두 번 세지 않게 센 것에 표시하며 세요."],"asset":{"type":"cards","topic":"animal","items":[["수찬","개"],["채원","앵무새"],["지아","개"],["서준","고양이"],["재이","토끼"],["효주","고양이"],["슬기","금붕어"],["정우","금붕어"],["세미","앵무새"],["민하","개"],["연우","금붕어"],["호진","고양이"],["소민","개"],["우영","금붕어"],["지은","고양이"],["다윤","토끼"],["소희","개"],["도현","앵무새"],["시후","고양이"],["상혁","개"]]},"variant_rule":{"alt":[{"stem":"자료를 보세요. 앵무새를 좋아하는 학생은 몇 명인가요?","explanation":["자료에서 「앵무새」를 고른 이름표만 ／ 표시를 하며 세어요.","앵무새를 좋아하는 학생은 3명이에요.","빠뜨리거나 두 번 세지 않게 센 것에 표시하며 세요."],"asset":{"type":"cards","topic":"animal","items":[["수찬","개"],["채원","앵무새"],["지아","개"],["서준","고양이"],["재이","토끼"],["효주","고양이"],["슬기","금붕어"],["정우","금붕어"],["세미","앵무새"],["민하","개"],["연우","금붕어"],["호진","고양이"],["소민","개"],["우영","금붕어"],["지은","고양이"],["다윤","토끼"],["소희","개"],["도현","앵무새"],["시후","고양이"],["상혁","개"]]},"options":[{"t":"3명","correct":true},{"t":"4명","mis":"M2-2-u5-X01"},{"t":"2명","mis":"M2-2-u5-X01"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_basic#2','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C6',1,'mc','auto','수찬이네 반 학생들이 좋아하는 동물 붙임딱지를 붙여 분류해요. 「개는 어디에 붙여야 할까요?」 하는 물음에 알맞은 방법은 어느 것인가요?',ARRAY['M2-2-u5-X10']::text[],false,'{"seq":2,"concept":"M2-2-u5-C6","difficulty":1,"kind":"mc","stem":"수찬이네 반 학생들이 좋아하는 동물 붙임딱지를 붙여 분류해요. 「개는 어디에 붙여야 할까요?」 하는 물음에 알맞은 방법은 어느 것인가요?","options":[{"t":"개 칸에 같은 종류끼리 아래에서 위로 하나씩 순서대로 붙인다","correct":true},{"t":"개 칸의 맨 위부터 아래로 붙인다","mis":"M2-2-u5-X10"},{"t":"한 칸씩 띄우면서 붙인다","mis":"M2-2-u5-X10"}],"explanation":["같은 종류끼리 모아 붙여요.","아래에서 위로 하나씩 순서대로, 빈칸 없이 붙여요.","그러면 그래프 모양이 되어 많고 적음이 한눈에 보여요."],"asset":{"type":"cards","topic":"animal","items":[["수찬","개"],["채원","앵무새"],["지아","개"],["서준","고양이"],["재이","토끼"],["효주","고양이"],["슬기","금붕어"],["정우","금붕어"],["세미","앵무새"],["민하","개"],["연우","금붕어"],["호진","고양이"],["소민","개"],["우영","금붕어"],["지은","고양이"],["다윤","토끼"],["소희","개"],["도현","앵무새"],["시후","고양이"],["상혁","개"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_basic#3','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C5',1,'sa','auto','고양이를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u5-C5","difficulty":1,"kind":"sa","stem":"고양이를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["5","5명"],"explanation":["그래프에서 「고양이」 칸에 ◯가 몇 개 그려졌는지 세어요.","고양이를 좋아하는 학생은 5명이에요.","한 칸에 하나씩 — 그려진 수가 곧 그 항목의 수예요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"금붕어를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["그래프에서 「금붕어」 칸에 ◯가 몇 개 그려졌는지 세어요.","금붕어를 좋아하는 학생은 4명이에요.","한 칸에 하나씩 — 그려진 수가 곧 그 항목의 수예요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"},"answer":["4","4명"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_basic#4','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C5',1,'mc','auto','표를 보고 그래프로 나타내려고 해요. 세로는 적어도 몇 칸으로 나누어야 하나요?',ARRAY['M2-2-u5-X12']::text[],true,'{"seq":4,"concept":"M2-2-u5-C5","difficulty":1,"kind":"mc","stem":"표를 보고 그래프로 나타내려고 해요. 세로는 적어도 몇 칸으로 나누어야 하나요?","options":[{"t":"6칸","correct":true},{"t":"20칸","mis":"M2-2-u5-X12"},{"t":"5칸","mis":"M2-2-u5-X12"}],"explanation":["가장 큰 수는 개 6명이에요.","◯를 6개까지 그려야 하니 세로는 6칸이면 돼요.","칸이 모자라면 다 그릴 수 없고, 너무 많으면 빈 칸이 남아요."],"asset":{"type":"ftable","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","total":20},"variant_rule":{"alt":[{"stem":"표를 보고 그래프로 나타내려고 해요. 가로는 적어도 몇 칸으로 나누어야 하나요?","explanation":["가장 큰 수는 팥 7명이에요.","／을 7개까지 그려야 하니 가로는 7칸이면 돼요.","칸이 모자라면 다 그릴 수 없고, 너무 많으면 빈 칸이 남아요."],"asset":{"type":"ftable","topic":"bread","title":"재우네 반 학생들이 좋아하는 붕어빵의 종류별 학생 수","head":"종류","cols":["팥","슈크림","고구마","치즈","초코"],"counts":[7,5,2,3,4],"unit":"명","vh":"학생 수","total":21},"options":[{"t":"7칸","correct":true},{"t":"21칸","mis":"M2-2-u5-X12"},{"t":"5칸","mis":"M2-2-u5-X12"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_basic#5','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C5',2,'match','auto','그래프를 나타내는 순서에 맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"M2-2-u5-C5","difficulty":2,"kind":"match","stem":"그래프를 나타내는 순서에 맞게 이으세요.","pairs":[{"l":"①","r":"가로와 세로에 어떤 것을 나타낼지 정한다"},{"l":"②","r":"가로와 세로를 각각 몇 칸으로 할지 정한다"},{"l":"③","r":"◯, ×, ／ 중 하나를 골라 자료를 나타낸다"},{"l":"④","r":"그래프의 제목을 쓴다"}],"mis":"M2-2-u5-X15","explanation":["먼저 가로와 세로에 무엇을 나타낼지 정하고 칸 수를 정해요.","◯, ×, ／ 가운데 하나만 골라 학생 수만큼 나타내요.","제목은 그래프를 다 그린 뒤에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_basic#6','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C5',2,'ox','auto','동물과 학생 수(명)의 자리를 바꾸어 ×로 그린 그래프는 ◯로 그린 그래프와 동물별 학생 수가 달라요.',ARRAY['M2-2-u5-X13']::text[],true,'{"seq":6,"concept":"M2-2-u5-C5","difficulty":2,"kind":"ox","stem":"동물과 학생 수(명)의 자리를 바꾸어 ×로 그린 그래프는 ◯로 그린 그래프와 동물별 학생 수가 달라요.","answer":"X","reason_options":[{"t":"자리와 기호만 바뀌고 동물 종류와 학생 수는 같으니까","correct":true},{"t":"그래프 모양이 달라지면 수도 달라지니까","mis":"M2-2-u5-X13"}],"mis":"M2-2-u5-X13","explanation":["교과서에서 두 그래프의 같은 점은 동물 종류와 학생 수예요.","다른 점은 동물과 학생 수(명)의 위치, 표시하는 기호예요.","개 6명은 세로로 쌓아도 가로로 늘어놓아도 6개예요."],"asset":{"type":"pgraph","mark":"×","dir":"h","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"같은 표를 보고 ◯로 세로로 그린 그래프와 ×로 가로로 그린 그래프는 동물 종류와 학생 수가 같아요.","answer":"O","reason_options":[{"t":"같은 표를 보고 그린 것이라 종류와 수가 같으니까","correct":true},{"t":"기호가 다르면 수도 다르니까","mis":"M2-2-u5-X13"}],"explanation":["같은 자료를 두 가지 모양으로 나타낸 거예요.","기호와 자리가 달라도 종류와 수는 같아요.","개 6명은 어느 그래프에서도 6개예요."],"asset":{"type":"pgraph","mark":"×","dir":"h","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_basic#7','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C6',2,'sa','auto','표를 보고 그래프를 완성하려고 해요. 토끼 칸에는 ◯를 몇 개 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u5-C6","difficulty":2,"kind":"sa","stem":"표를 보고 그래프를 완성하려고 해요. 토끼 칸에는 ◯를 몇 개 그려야 하나요? 숫자로 쓰세요.","answer":["2","2개"],"explanation":["표에서 토끼는 2명이에요.","그래프의 수는 표의 수와 같아야 해요 — ◯를 2개 그려요.","맨 아래 칸부터 빠짐없이 한 칸에 하나씩 그려요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","table":true,"blank":[3]},"variant_rule":{"alt":[{"stem":"표를 보고 그래프를 완성하려고 해요. 앵무새 칸에는 ◯를 몇 개 그려야 하나요? 숫자로 쓰세요.","explanation":["표에서 앵무새는 3명이에요.","그래프의 수는 표의 수와 같아야 해요 — ◯를 3개 그려요.","맨 아래 칸부터 빠짐없이 한 칸에 하나씩 그려요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","table":true,"blank":[1]},"answer":["3","3개"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_basic#8','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C6',2,'mc','auto','슈크림 붕어빵을 좋아하는 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01']::text[],true,'{"seq":8,"concept":"M2-2-u5-C6","difficulty":2,"kind":"mc","stem":"슈크림 붕어빵을 좋아하는 학생은 몇 명인가요?","options":[{"t":"5명","correct":true},{"t":"6명","mis":"M2-2-u5-X01"},{"t":"4명","mis":"M2-2-u5-X01"}],"explanation":["그래프에서 「슈크림」 칸에 ／이 몇 개 그려졌는지 세어요.","슈크림 붕어빵을 좋아하는 학생은 5명이에요.","한 칸에 하나씩 — 그려진 수가 곧 그 항목의 수예요."],"asset":{"type":"pgraph","mark":"／","dir":"h","topic":"bread","title":"재우네 반 학생들이 좋아하는 붕어빵의 종류별 학생 수","head":"종류","cols":["팥","슈크림","고구마","치즈","초코"],"counts":[7,5,2,3,4],"unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"초코 붕어빵을 좋아하는 학생은 몇 명인가요?","explanation":["그래프에서 「초코」 칸에 ／이 몇 개 그려졌는지 세어요.","초코 붕어빵을 좋아하는 학생은 4명이에요.","한 칸에 하나씩 — 그려진 수가 곧 그 항목의 수예요."],"asset":{"type":"pgraph","mark":"／","dir":"h","topic":"bread","title":"재우네 반 학생들이 좋아하는 붕어빵의 종류별 학생 수","head":"종류","cols":["팥","슈크림","고구마","치즈","초코"],"counts":[7,5,2,3,4],"unit":"명","vh":"학생 수"},"options":[{"t":"4명","correct":true},{"t":"5명","mis":"M2-2-u5-X01"},{"t":"3명","mis":"M2-2-u5-X01"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_basic#9','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C6',2,'ox','auto','세미가 개 칸의 ◯를 다른 칸의 ◯보다 크게 그렸어요. 그래서 개를 좋아하는 학생이 6명보다 많아졌어요.',ARRAY['M2-2-u5-X18']::text[],false,'{"seq":9,"concept":"M2-2-u5-C6","difficulty":2,"kind":"ox","stem":"세미가 개 칸의 ◯를 다른 칸의 ◯보다 크게 그렸어요. 그래서 개를 좋아하는 학생이 6명보다 많아졌어요.","answer":"X","reason_options":[{"t":"◯ 하나는 크기와 상관없이 한 명을 나타내니까","correct":true},{"t":"◯가 크면 더 많은 학생을 나타내니까","mis":"M2-2-u5-X18"}],"mis":"M2-2-u5-X18","explanation":["그래프의 ◯ 하나는 학생 한 명이에요.","◯의 크기는 학생 수와 관련이 없어요.","개 칸에 ◯가 6개이면 크게 그려도 6명이에요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_basic#10','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C6',3,'mc','auto','표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?',ARRAY['M2-2-u5-X11']::text[],true,'{"seq":10,"concept":"M2-2-u5-C6","difficulty":3,"kind":"mc","stem":"표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?","options":[{"t":"앵무새 — 표는 3명인데 ◯를 4개 그렸다","correct":true},{"t":"개 — 표는 6명인데 ◯를 5개 그렸다","mis":"M2-2-u5-X11"},{"t":"고양이 — 표는 5명인데 ◯를 4개 그렸다","mis":"M2-2-u5-X11"},{"t":"토끼 — 표는 2명인데 ◯를 3개 그렸다","mis":"M2-2-u5-X11"}],"explanation":["표에서 앵무새는 3명인데 그래프에는 ◯가 4개예요.","표와 그래프의 수는 반드시 같아야 해요.","다른 칸은 표의 수와 그래프의 수가 같아요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","table":true,"drawn":[6,4,5,2,4]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?","explanation":["표에서 금붕어는 4명인데 그래프에는 ◯가 3개예요.","표와 그래프의 수는 반드시 같아야 해요.","다른 칸은 표의 수와 그래프의 수가 같아요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","table":true,"drawn":[6,3,5,2,3]},"options":[{"t":"금붕어 — 표는 4명인데 ◯를 3개 그렸다","correct":true},{"t":"개 — 표는 6명인데 ◯를 5개 그렸다","mis":"M2-2-u5-X11"},{"t":"앵무새 — 표는 3명인데 ◯를 4개 그렸다","mis":"M2-2-u5-X11"},{"t":"고양이 — 표는 5명인데 ◯를 4개 그렸다","mis":"M2-2-u5-X11"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_challenge#1','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C6',2,'mc','auto','그래프를 보세요. 잘못 그린 까닭은 무엇인가요?',ARRAY['M2-2-u5-X10','M2-2-u5-X13']::text[],true,'{"seq":1,"concept":"M2-2-u5-C6","difficulty":2,"kind":"mc","stem":"그래프를 보세요. 잘못 그린 까닭은 무엇인가요?","options":[{"t":"중간 칸을 건너뛰고 그렸다","correct":true},{"t":"맨 아래 칸부터 채우지 않고 위에서부터 그렸다","mis":"M2-2-u5-X10"},{"t":"기호를 섞어서 그렸다","mis":"M2-2-u5-X13"}],"explanation":["「개」 칸을 보세요.","◯가 중간 한 칸을 비우고 그 다음 칸에 그려져 있어요.","맨 아래부터 빠짐없이, 한 가지 기호로 그려요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","rows":7,"bad":{"col":0,"how":"skip"}},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그래프를 보세요. 잘못 그린 까닭은 무엇인가요?","explanation":["「고양이」 칸을 보세요.","◯가 위에서부터 채워져 있어요.","맨 아래부터 빠짐없이, 한 가지 기호로 그려요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","rows":6,"bad":{"col":2,"how":"top"}},"options":[{"t":"맨 아래 칸부터 채우지 않고 위에서부터 그렸다","correct":true},{"t":"중간 칸을 건너뛰고 그렸다","mis":"M2-2-u5-X10"},{"t":"기호를 섞어서 그렸다","mis":"M2-2-u5-X13"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_challenge#2','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C6',2,'sa','auto','금붕어를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u5-C6","difficulty":2,"kind":"sa","stem":"금붕어를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["4","4명"],"explanation":["그래프에서 「금붕어」 칸에 ×가 몇 개 그려졌는지 세어요.","금붕어를 좋아하는 학생은 4명이에요.","한 칸에 하나씩 — 그려진 수가 곧 그 항목의 수예요."],"asset":{"type":"pgraph","mark":"×","dir":"h","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"앵무새를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["그래프에서 「앵무새」 칸에 ×가 몇 개 그려졌는지 세어요.","앵무새를 좋아하는 학생은 3명이에요.","한 칸에 하나씩 — 그려진 수가 곧 그 항목의 수예요."],"asset":{"type":"pgraph","mark":"×","dir":"h","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"},"answer":["3","3명"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_challenge#3','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C5',3,'sa','auto','표를 보고 그래프로 나타내려고 해요. 가로는 적어도 몇 칸으로 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M2-2-u5-C5","difficulty":3,"kind":"sa","stem":"표를 보고 그래프로 나타내려고 해요. 가로는 적어도 몇 칸으로 나누어야 하나요? 숫자로 쓰세요.","answer":["7","7칸"],"explanation":["가장 큰 수는 팥 7명이에요.","／을 7개까지 그려야 하니 가로는 7칸이면 돼요.","칸이 모자라면 다 그릴 수 없고, 너무 많으면 빈 칸이 남아요."],"asset":{"type":"ftable","topic":"bread","title":"재우네 반 학생들이 좋아하는 붕어빵의 종류별 학생 수","head":"종류","cols":["팥","슈크림","고구마","치즈","초코"],"counts":[7,5,2,3,4],"unit":"명","vh":"학생 수","total":21}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_challenge#4','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C6',3,'blank','auto','『수학익힘』에서 붕어빵 가게 주인이 되어 재우네 반 학생들에게 편지를 써요. 「그래프를 보니 재우네 반에서 가장 많은 학생들이 좋아하는 붕어빵은 ( ) 붕어빵이구나.」 ( )에 알맞은 말은 무엇인가요?',ARRAY['M2-2-u5-X07','M2-2-u5-X09']::text[],false,'{"seq":4,"concept":"M2-2-u5-C6","difficulty":3,"kind":"blank","stem":"『수학익힘』에서 붕어빵 가게 주인이 되어 재우네 반 학생들에게 편지를 써요. 「그래프를 보니 재우네 반에서 가장 많은 학생들이 좋아하는 붕어빵은 ( ) 붕어빵이구나.」 ( )에 알맞은 말은 무엇인가요?","options":[{"t":"팥","correct":true},{"t":"초코","mis":"M2-2-u5-X07"},{"t":"고구마","mis":"M2-2-u5-X09"}],"explanation":["／가 가장 길게 늘어선 줄을 찾아요.","팥 붕어빵이 7명으로 가장 많아요.","맨 위 줄에 있다고 많은 것이 아니에요 — 초코는 4명이에요."],"asset":{"type":"pgraph","mark":"／","dir":"h","topic":"bread","title":"재우네 반 학생들이 좋아하는 붕어빵의 종류별 학생 수","head":"종류","cols":["팥","슈크림","고구마","치즈","초코"],"counts":[7,5,2,3,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_challenge#5','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C5',3,'error','auto','수찬이네 반 동물 그래프를 ◯로 그린 것과 ×로 그린 것을 비교했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X13']::text[],false,'{"seq":5,"concept":"M2-2-u5-C5","difficulty":3,"kind":"error","stem":"수찬이네 반 동물 그래프를 ◯로 그린 것과 ×로 그린 것을 비교했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다온 — 「◯ 그래프와 × 그래프는 동물별 학생 수가 달라.」","correct":true,"mis_target":"M2-2-u5-X13"},{"t":"민솔 — 「동물과 학생 수(명)의 위치가 달라.」","mis":"M2-2-u5-X13"},{"t":"지후 — 「표시하는 기호가 달라.」","mis":"M2-2-u5-X13"}],"explanation":["두 그래프는 같은 표를 보고 그린 거예요.","위치와 기호는 달라도 동물 종류와 학생 수는 같아요.","그래서 다온이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_challenge#6','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C6',3,'error','auto','앵무새를 좋아하는 학생 3명을 세로 6칸 그래프에 나타내는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X10']::text[],false,'{"seq":6,"concept":"M2-2-u5-C6","difficulty":3,"kind":"error","stem":"앵무새를 좋아하는 학생 3명을 세로 6칸 그래프에 나타내는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「6칸부터 4칸까지 위에서부터 채워.」","correct":true,"mis_target":"M2-2-u5-X10"},{"t":"윤슬 — 「1칸부터 3칸까지 차례로 채워.」","mis":"M2-2-u5-X10"},{"t":"채윤 — 「◯를 한 칸에 하나씩 3개 그려.」","mis":"M2-2-u5-X10"}],"explanation":["◯는 맨 아래 1칸부터 3칸까지 차례로 채워요.","위에서부터 채우면 안 돼요.","한 칸에 하나씩, 3명이니 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_challenge#7','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C5',3,'ox','auto','가장 많은 수가 6명이면 세로를 10칸으로 나누어야 해요.',ARRAY['M2-2-u5-X12']::text[],false,'{"seq":7,"concept":"M2-2-u5-C5","difficulty":3,"kind":"ox","stem":"가장 많은 수가 6명이면 세로를 10칸으로 나누어야 해요.","answer":"X","reason_options":[{"t":"가장 큰 수 6만큼 6칸이면 되고 더 나누면 빈 칸이 남으니까","correct":true},{"t":"칸은 많을수록 좋으니까","mis":"M2-2-u5-X12"}],"mis":"M2-2-u5-X12","explanation":["세로 칸 수는 가장 큰 수만큼이면 돼요.","개 6명이 가장 많으니 6칸이에요.","10칸으로 나누면 위에 빈 칸이 많이 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_challenge#8','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C6',4,'essay','teacher','◯를 맨 아래 칸부터 빠짐없이 채워야 하는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u5-C6","difficulty":4,"kind":"essay","stem":"◯를 맨 아래 칸부터 빠짐없이 채워야 하는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 맨 아래부터 빠짐없이 채워야 ◯의 높이를 보고 몇 명인지 바로 알 수 있고, 어느 동물이 많고 적은지 한눈에 견줄 수 있다. 위에서부터 그리거나 중간을 건너뛰면 수를 잘못 읽게 된다.","scoring_points":["높이로 수를 읽을 수 있음을 썼는가","많고 적음을 견줄 수 있음을 썼는가","건너뛰거나 위에서 그리면 안 되는 까닭을 썼는가"]},"explanation":["맨 아래부터 채우면 높이가 곧 수예요.","그래서 많고 적음을 한눈에 견줄 수 있어요.","건너뛰거나 위에서 그리면 수를 잘못 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_challenge#9','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C5',4,'essay','teacher','수찬이네 반 표를 보고 그래프로 나타내는 차례를 설명하고, 붙임딱지로 분류했을 때보다 그래프로 나타내면 좋은 점을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u5-C5","difficulty":4,"kind":"essay","stem":"수찬이네 반 표를 보고 그래프로 나타내는 차례를 설명하고, 붙임딱지로 분류했을 때보다 그래프로 나타내면 좋은 점을 써 보세요.","answer_guide":{"answer":"예: 학생 수(명) 칸에 1부터 6까지 수를 쓰고, 동물 이름을 쓴 뒤, 학생 수만큼 ◯를 맨 아래부터 그리고, 마지막에 표와 같은 제목을 쓴다. 붙임딱지는 하나씩 붙이며 세는 것이 번거롭지만 그래프는 ◯로 간단히 나타내 좋아하는 동물을 한눈에 알아보기 쉽다.","scoring_points":["칸에 수·동물 이름을 쓰는 차례를 썼는가","학생 수만큼 ◯를 그리고 제목을 쓰는 차례를 썼는가","그래프의 편리한 점(한눈에)을 썼는가"]},"explanation":["수와 동물 이름을 먼저 쓰고 학생 수만큼 ◯를 그려요.","제목은 표와 같이, 다 그린 뒤에 써요.","그래프는 많고 적음을 한눈에 알아보기 쉬워요."],"asset":{"type":"ftable","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L04_challenge#10','math',2,2,'u5','L04','tb_g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C5',4,'mc','auto','읽을거리의 「학생들이 배우고 싶어 하는 악기별 학생 수」는 리코더 2명, 피아노 6명, 칼림바 4명, 오카리나 2명이에요. 이것을 ×를 써서 가로로 된 그래프로 나타내는 방법을 바르게 말한 것은 무엇인가요?',ARRAY['M2-2-u5-X12','M2-2-u5-X13','M2-2-u5-X18']::text[],false,'{"seq":10,"concept":"M2-2-u5-C5","difficulty":4,"kind":"mc","stem":"읽을거리의 「학생들이 배우고 싶어 하는 악기별 학생 수」는 리코더 2명, 피아노 6명, 칼림바 4명, 오카리나 2명이에요. 이것을 ×를 써서 가로로 된 그래프로 나타내는 방법을 바르게 말한 것은 무엇인가요?","options":[{"t":"가로를 6칸으로 나누고 피아노 줄에는 ×를 왼쪽부터 빠짐없이 6개 그린다","correct":true},{"t":"가로를 14칸으로 나누고 피아노 줄에 ×를 6개 그린다","mis":"M2-2-u5-X12"},{"t":"리코더 줄은 ×를, 오카리나 줄은 ／를 그린다","mis":"M2-2-u5-X13"},{"t":"피아노 줄은 ×를 크게 2개만 그린다","mis":"M2-2-u5-X18"}],"explanation":["가장 큰 수는 피아노 6명이니 가로는 6칸이면 돼요.","한 가지 기호로 한 칸에 하나씩, 왼쪽부터 빠짐없이 그려요.","14는 합계예요. 기호를 크게 그려도 한 개는 한 명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_basic#1','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',1,'sa','auto','동호네 반 학생 수는 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M2-2-u5-C7","difficulty":1,"kind":"sa","stem":"동호네 반 학생 수는 모두 몇 명인가요? 숫자로 쓰세요.","answer":["22","22명"],"explanation":["표의 전통 놀이별 수는 비사치기 3명, 투호 놀이 8명, 제기차기 2명, 공기놀이 9명이에요.","3 + 8 + 2 + 9 = 22이니 모두 22명이에요.","항목별 수를 모두 더한 것이 합계 — 전체 수예요."],"asset":{"type":"ftable","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","total":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_basic#2','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',1,'mc','auto','가장 많은 학생들이 좋아하는 전통 놀이는 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],true,'{"seq":2,"concept":"M2-2-u5-C7","difficulty":1,"kind":"mc","stem":"가장 많은 학생들이 좋아하는 전통 놀이는 무엇인가요?","options":[{"t":"공기놀이","correct":true},{"t":"제기차기","mis":"M2-2-u5-X09"},{"t":"비사치기","mis":"M2-2-u5-X07"},{"t":"투호 놀이","mis":"M2-2-u5-X07"}],"explanation":["그래프에서 ◯가 가장 높이 쌓인 칸을 찾아요.","비사치기 3명, 투호 놀이 8명, 제기차기 2명, 공기놀이 9명이에요 — 가장 많은 것은 공기놀이(9명)예요.","「가장 많은」을 묻는지 다시 읽어요. 앞 칸이라고 많은 게 아니에요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"가장 적은 학생들이 좋아하는 전통 놀이는 무엇인가요?","explanation":["그래프에서 ◯가 가장 낮게 쌓인 칸을 찾아요.","비사치기 3명, 투호 놀이 8명, 제기차기 2명, 공기놀이 9명이에요 — 가장 적은 것은 제기차기(2명)예요.","「가장 적은」을 묻는지 다시 읽어요. 앞 칸이라고 많은 게 아니에요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"},"options":[{"t":"제기차기","correct":true},{"t":"공기놀이","mis":"M2-2-u5-X09"},{"t":"비사치기","mis":"M2-2-u5-X07"},{"t":"투호 놀이","mis":"M2-2-u5-X07"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_basic#3','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',1,'sa','auto','비사치기를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u5-C7","difficulty":1,"kind":"sa","stem":"비사치기를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["3","3명"],"explanation":["표에서 「비사치기」 칸 아래의 수를 읽어요.","비사치기를 좋아하는 학생은 3명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"asset":{"type":"ftable","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","total":22},"variant_rule":{"alt":[{"stem":"공기놀이를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["표에서 「공기놀이」 칸 아래의 수를 읽어요.","공기놀이를 좋아하는 학생은 9명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"asset":{"type":"ftable","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","total":22},"answer":["9","9명"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_basic#4','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',1,'match','auto','무엇을 알기에 편리한지 알맞게 이으세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u5-C7","difficulty":1,"kind":"match","stem":"무엇을 알기에 편리한지 알맞게 이으세요.","pairs":[{"l":"표","r":"항목별 수와 합계를 쉽게 알기"},{"l":"그래프","r":"많고 적음을 한눈에 비교하기"},{"l":"자료(이름표)","r":"누가 무엇을 골랐는지 알기"}],"mis":"M2-2-u5-X16","explanation":["표에서는 전통 놀이별 학생 수를 쉽게 알 수 있어요.","그래프는 전체적인 비교를 쉽게 할 수 있어요.","누가 무엇을 골랐는지는 자료에서 알아요."],"variant_rule":{"alt":[{"stem":"알고 싶은 것과 편리한 것을 이으세요.","pairs":[{"l":"공기놀이를 좋아하는 학생은 몇 명인지 바로 알기","r":"표"},{"l":"어느 놀이를 가장 많이 좋아하는지 한눈에 보기","r":"그래프"}],"explanation":["수를 바로 읽을 때는 표가 편리해요.","많고 적음을 한눈에 볼 때는 그래프가 편리해요.","같은 자료라도 쓰임이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_basic#5','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',2,'mc','auto','동호네 반 그래프에서 3명보다 많은 학생들이 좋아하는 전통 놀이를 모두 고르면 어느 것인가요?',ARRAY['M2-2-u5-X14','M2-2-u5-X09']::text[],false,'{"seq":5,"concept":"M2-2-u5-C7","difficulty":2,"kind":"mc","stem":"동호네 반 그래프에서 3명보다 많은 학생들이 좋아하는 전통 놀이를 모두 고르면 어느 것인가요?","options":[{"t":"투호 놀이, 공기놀이","correct":true},{"t":"비사치기, 투호 놀이, 공기놀이","mis":"M2-2-u5-X14"},{"t":"비사치기, 제기차기","mis":"M2-2-u5-X09"}],"explanation":["3명인 칸에 선을 긋고 그 위에 ◯가 있는 놀이를 찾아요.","투호 놀이 8명, 공기놀이 9명이에요.","「3명보다 많은」에 딱 3명인 비사치기는 들어가지 않아요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_basic#6','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',2,'sa','auto','공기놀이를 좋아하는 학생은 투호 놀이를 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u5-C7","difficulty":2,"kind":"sa","stem":"공기놀이를 좋아하는 학생은 투호 놀이를 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["1","1명"],"explanation":["공기놀이를 좋아하는 학생은 9명, 투호 놀이를 좋아하는 학생은 8명이에요.","9 − 8 = 1이니 1명 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"asset":{"type":"ftable","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","total":22},"variant_rule":{"alt":[{"stem":"투호 놀이를 좋아하는 학생은 제기차기를 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","explanation":["투호 놀이를 좋아하는 학생은 8명, 제기차기를 좋아하는 학생은 2명이에요.","8 − 2 = 6이니 6명 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"asset":{"type":"ftable","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","total":22},"answer":["6","6명"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_basic#7','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',2,'ox','auto','「3명보다 많은」 전통 놀이를 찾을 때 딱 3명인 비사치기도 들어가요.',ARRAY['M2-2-u5-X14']::text[],false,'{"seq":7,"concept":"M2-2-u5-C7","difficulty":2,"kind":"ox","stem":"「3명보다 많은」 전통 놀이를 찾을 때 딱 3명인 비사치기도 들어가요.","answer":"X","reason_options":[{"t":"3명은 3명보다 많은 것이 아니니까","correct":true},{"t":"3명도 3명보다 많으니까","mis":"M2-2-u5-X14"}],"mis":"M2-2-u5-X14","explanation":["「3명보다 많은」은 4명, 5명……처럼 3보다 큰 수예요.","비사치기는 딱 3명이라 들어가지 않아요.","3명 자리에 선을 긋고 그 위에 ◯가 있는 놀이만 찾아요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_basic#8','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',2,'mc','auto','4모둠의 제기차기 횟수는 몇 회인가요?',ARRAY['M2-2-u5-X01','M2-2-u5-X02']::text[],true,'{"seq":8,"concept":"M2-2-u5-C7","difficulty":2,"kind":"mc","stem":"4모둠의 제기차기 횟수는 몇 회인가요?","options":[{"t":"13회","correct":true},{"t":"14회","mis":"M2-2-u5-X01"},{"t":"12회","mis":"M2-2-u5-X01"},{"t":"5회","mis":"M2-2-u5-X02"}],"explanation":["그래프에서 「4모둠」 칸에 ◯가 몇 개 그려졌는지 세어요.","4모둠의 제기차기 횟수는 13회예요.","한 칸에 하나씩 — 그려진 수가 곧 그 항목의 수예요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"jegi","title":"지수네 반 모둠별 제기차기 횟수","head":"모둠","cols":["1모둠","2모둠","3모둠","4모둠","5모둠"],"counts":[5,3,7,13,8],"unit":"회","vh":"횟수"},"variant_rule":{"alt":[{"stem":"3모둠의 제기차기 횟수는 몇 회인가요?","explanation":["그래프에서 「3모둠」 칸에 ◯가 몇 개 그려졌는지 세어요.","3모둠의 제기차기 횟수는 7회예요.","한 칸에 하나씩 — 그려진 수가 곧 그 항목의 수예요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"jegi","title":"지수네 반 모둠별 제기차기 횟수","head":"모둠","cols":["1모둠","2모둠","3모둠","4모둠","5모둠"],"counts":[5,3,7,13,8],"unit":"회","vh":"횟수"},"options":[{"t":"7회","correct":true},{"t":"8회","mis":"M2-2-u5-X01"},{"t":"6회","mis":"M2-2-u5-X01"},{"t":"5회","mis":"M2-2-u5-X02"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_basic#9','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',2,'mc','auto','가장 적은 학생들이 좋아하는 간식은 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],true,'{"seq":9,"concept":"M2-2-u5-C7","difficulty":2,"kind":"mc","stem":"가장 적은 학생들이 좋아하는 간식은 무엇인가요?","options":[{"t":"라면","correct":true},{"t":"떡볶이","mis":"M2-2-u5-X09"},{"t":"햄버거","mis":"M2-2-u5-X07"}],"explanation":["표에서 수가 가장 작은 칸을 찾아요.","햄버거 5명, 떡볶이 8명, 김밥 4명, 라면 2명이에요 — 가장 적은 것은 라면(2명)이에요.","「가장 적은」을 묻는지 다시 읽어요. 앞 칸이라고 많은 게 아니에요."],"asset":{"type":"ftable","topic":"snack","title":"주영이네 반 학생들이 좋아하는 간식별 학생 수","head":"간식","cols":["햄버거","떡볶이","김밥","라면"],"counts":[5,8,4,2],"unit":"명","vh":"학생 수","total":19},"variant_rule":{"alt":[{"stem":"가장 많은 학생들이 좋아하는 간식은 무엇인가요?","explanation":["표에서 수가 가장 큰 칸을 찾아요.","햄버거 5명, 떡볶이 8명, 김밥 4명, 라면 2명이에요 — 가장 많은 것은 떡볶이(8명)예요.","「가장 많은」을 묻는지 다시 읽어요. 앞 칸이라고 많은 게 아니에요."],"asset":{"type":"ftable","topic":"snack","title":"주영이네 반 학생들이 좋아하는 간식별 학생 수","head":"간식","cols":["햄버거","떡볶이","김밥","라면"],"counts":[5,8,4,2],"unit":"명","vh":"학생 수","total":19},"options":[{"t":"떡볶이","correct":true},{"t":"라면","mis":"M2-2-u5-X09"},{"t":"햄버거","mis":"M2-2-u5-X07"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_basic#10','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',3,'error','auto','동호네 반 표와 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X07','M2-2-u5-X16']::text[],true,'{"seq":10,"concept":"M2-2-u5-C7","difficulty":3,"kind":"error","stem":"동호네 반 표와 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"채윤 — 「그래프에서 비사치기가 맨 앞에 있으니까 가장 많아.」","correct":true,"mis_target":"M2-2-u5-X07"},{"t":"하람 — 「공기놀이가 가장 높이 쌓여서 가장 많아.」","mis":"M2-2-u5-X16"},{"t":"윤슬 — 「표를 보면 투호 놀이는 8명이야.」","mis":"M2-2-u5-X16"}],"explanation":["많고 적음은 ◯의 높이로 견주어요.","맨 앞 칸이라고 많은 게 아니에요 — 비사치기는 3명이에요.","가장 높이 쌓인 공기놀이(9명)가 가장 많아요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","table":true},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 동호네 반 표와 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「공기놀이 칸이 가장 뒤에 있으니까 가장 적어.」","correct":true,"mis_target":"M2-2-u5-X07"},{"t":"가은 — 「◯가 가장 낮게 쌓인 제기차기가 가장 적어.」","mis":"M2-2-u5-X16"},{"t":"태오 — 「동호네 반은 합계 22명이야.」","mis":"M2-2-u5-X16"}],"explanation":["많고 적음은 칸의 자리가 아니라 ◯의 높이로 견주어요.","공기놀이는 맨 뒤에 있지만 9명으로 가장 많아요.","가장 적은 것은 ◯가 가장 낮은 제기차기(2명)예요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","table":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_challenge#1','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',2,'mc','auto','비사치기를 좋아하는 학생과 제기차기를 좋아하는 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X03']::text[],true,'{"seq":1,"concept":"M2-2-u5-C7","difficulty":2,"kind":"mc","stem":"비사치기를 좋아하는 학생과 제기차기를 좋아하는 학생은 모두 몇 명인가요?","options":[{"t":"5명","correct":true},{"t":"1명","mis":"M2-2-u5-X08"},{"t":"22명","mis":"M2-2-u5-X03"}],"explanation":["비사치기를 좋아하는 학생은 3명, 제기차기를 좋아하는 학생은 2명이에요.","3 + 2 = 5이니 모두 5명이에요.","두 칸의 수를 더해요 — 전체 합계가 아니에요."],"asset":{"type":"ftable","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","total":22},"variant_rule":{"alt":[{"stem":"1모둠의 제기차기 횟수와 2모둠의 제기차기 횟수는 모두 몇 회인가요?","explanation":["1모둠의 제기차기 횟수는 5회, 2모둠의 제기차기 횟수는 3회예요.","5 + 3 = 8이니 모두 8회예요.","두 칸의 수를 더해요 — 전체 합계가 아니에요."],"asset":{"type":"ftable","topic":"jegi","title":"지수네 반 모둠별 제기차기 횟수","head":"모둠","cols":["1모둠","2모둠","3모둠","4모둠","5모둠"],"counts":[5,3,7,13,8],"unit":"회","vh":"횟수","total":36},"options":[{"t":"8회","correct":true},{"t":"2회","mis":"M2-2-u5-X08"},{"t":"36회","mis":"M2-2-u5-X03"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_challenge#2','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',2,'sa','auto','4명보다 많은 학생들이 좋아하는 간식은 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M2-2-u5-C7","difficulty":2,"kind":"sa","stem":"4명보다 많은 학생들이 좋아하는 간식은 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["2","2가지"],"explanation":["4명인 칸에 선을 긋고 그 위에 ◯가 있는 것을 찾아요.","햄버거, 떡볶이 — 2가지예요.","「4명보다 많은」에 딱 4명인 것은 들어가지 않아요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"snack","title":"주영이네 반 학생들이 좋아하는 간식별 학생 수","head":"간식","cols":["햄버거","떡볶이","김밥","라면"],"counts":[5,8,4,2],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_challenge#3','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',3,'mc','auto','4모둠의 제기차기 횟수는 1모둠의 제기차기 횟수보다 몇 회 더 많은가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X01']::text[],true,'{"seq":3,"concept":"M2-2-u5-C7","difficulty":3,"kind":"mc","stem":"4모둠의 제기차기 횟수는 1모둠의 제기차기 횟수보다 몇 회 더 많은가요?","options":[{"t":"8회","correct":true},{"t":"18회","mis":"M2-2-u5-X08"},{"t":"13회","mis":"M2-2-u5-X08"},{"t":"9회","mis":"M2-2-u5-X01"}],"explanation":["4모둠의 제기차기 횟수는 13회, 1모둠의 제기차기 횟수는 5회예요.","13 − 5 = 8이니 8회 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"asset":{"type":"ftable","topic":"jegi","title":"지수네 반 모둠별 제기차기 횟수","head":"모둠","cols":["1모둠","2모둠","3모둠","4모둠","5모둠"],"counts":[5,3,7,13,8],"unit":"회","vh":"횟수","total":36},"variant_rule":{"alt":[{"stem":"5모둠의 제기차기 횟수는 2모둠의 제기차기 횟수보다 몇 회 더 많은가요?","explanation":["5모둠의 제기차기 횟수는 8회, 2모둠의 제기차기 횟수는 3회예요.","8 − 3 = 5이니 5회 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"asset":{"type":"ftable","topic":"jegi","title":"지수네 반 모둠별 제기차기 횟수","head":"모둠","cols":["1모둠","2모둠","3모둠","4모둠","5모둠"],"counts":[5,3,7,13,8],"unit":"회","vh":"횟수","total":36},"options":[{"t":"5회","correct":true},{"t":"11회","mis":"M2-2-u5-X08"},{"t":"8회","mis":"M2-2-u5-X08"},{"t":"6회","mis":"M2-2-u5-X01"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_challenge#4','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',3,'mc','auto','동호네 반 그래프에서 5명보다 적은 학생들이 좋아하는 전통 놀이를 모두 고르면 어느 것인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X01']::text[],false,'{"seq":4,"concept":"M2-2-u5-C7","difficulty":3,"kind":"mc","stem":"동호네 반 그래프에서 5명보다 적은 학생들이 좋아하는 전통 놀이를 모두 고르면 어느 것인가요?","options":[{"t":"비사치기, 제기차기","correct":true},{"t":"투호 놀이, 공기놀이","mis":"M2-2-u5-X09"},{"t":"제기차기","mis":"M2-2-u5-X01"}],"explanation":["5명인 칸에 선을 긋고 그보다 아래까지만 ◯가 있는 놀이를 찾아요.","비사치기 3명, 제기차기 2명이에요.","「적은」을 「많은」으로 거꾸로 읽지 않아요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_challenge#5','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',3,'mc','auto','『수학익힘』 놀이터 문제예요. 2학년 학생들이 원하는 놀이기구를 조사한 그래프에서 ◯가 미끄럼틀 14개, 그네 5개, 회전 무대 13개, 시소 9개예요. 10명보다 많은 학생들이 원하는 놀이기구를 모두 고르면 어느 것인가요?',ARRAY['M2-2-u5-X01','M2-2-u5-X09']::text[],false,'{"seq":5,"concept":"M2-2-u5-C7","difficulty":3,"kind":"mc","stem":"『수학익힘』 놀이터 문제예요. 2학년 학생들이 원하는 놀이기구를 조사한 그래프에서 ◯가 미끄럼틀 14개, 그네 5개, 회전 무대 13개, 시소 9개예요. 10명보다 많은 학생들이 원하는 놀이기구를 모두 고르면 어느 것인가요?","options":[{"t":"미끄럼틀, 회전 무대","correct":true},{"t":"미끄럼틀","mis":"M2-2-u5-X01"},{"t":"그네, 시소","mis":"M2-2-u5-X09"}],"explanation":["10명인 자리에 선을 긋고 그 위에 ◯가 있는 놀이기구를 찾아요.","미끄럼틀 14명, 회전 무대 13명이에요.","시소 9명, 그네 5명은 10명보다 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_challenge#6','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',3,'error','auto','동호네 반 그래프를 보고 친구들이 말했어요. 그래프만으로는 알 수 없는 것을 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X16']::text[],false,'{"seq":6,"concept":"M2-2-u5-C7","difficulty":3,"kind":"error","stem":"동호네 반 그래프를 보고 친구들이 말했어요. 그래프만으로는 알 수 없는 것을 말한 친구는 누구인가요?","options":[{"t":"지후 — 「소희가 공기놀이를 좋아하는지 알 수 있어.」","correct":true,"mis_target":"M2-2-u5-X16"},{"t":"민솔 — 「가장 많은 학생들이 좋아하는 놀이를 알 수 있어.」","mis":"M2-2-u5-X16"},{"t":"다온 — 「투호 놀이보다 적은 학생들이 좋아하는 놀이를 알 수 있어.」","mis":"M2-2-u5-X16"}],"explanation":["그래프에는 놀이별 학생 수와 많고 적음이 나타나요.","누가 어떤 놀이를 좋아하는지는 자료에만 있어요.","가장 많은 놀이, 더 적은 놀이는 그래프로 알 수 있어요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_challenge#7','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',3,'ox','auto','동호네 반 그래프를 보면 공기놀이가 가장 재미있는 전통 놀이라는 것을 알 수 있어요.',ARRAY['M2-2-u5-X17']::text[],false,'{"seq":7,"concept":"M2-2-u5-C7","difficulty":3,"kind":"ox","stem":"동호네 반 그래프를 보면 공기놀이가 가장 재미있는 전통 놀이라는 것을 알 수 있어요.","answer":"X","reason_options":[{"t":"그래프는 좋아하는 학생 수를 나타낼 뿐 재미있는지는 나타내지 않으니까","correct":true},{"t":"공기놀이가 가장 높이 쌓였으니까","mis":"M2-2-u5-X17"}],"mis":"M2-2-u5-X17","explanation":["그래프로 알 수 있는 것은 공기놀이를 좋아하는 학생이 9명으로 가장 많다는 사실이에요.","「가장 재미있다」는 그래프에 나타나지 않은 생각이에요.","알 수 있는 내용은 그래프에 있는 수와 많고 적음으로 써요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_challenge#8','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',4,'essay','teacher','동호네 반 표와 그래프는 각각 어떤 것을 알기에 편리한지 예를 들어 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u5-C7","difficulty":4,"kind":"essay","stem":"동호네 반 표와 그래프는 각각 어떤 것을 알기에 편리한지 예를 들어 설명해 보세요.","answer_guide":{"answer":"예: 표는 투호 놀이가 8명이라는 것처럼 전통 놀이별 학생 수와 합계 22명을 쉽게 알 수 있다. 그래프는 공기놀이가 가장 높이 쌓여 가장 많다는 것처럼 많고 적음을 한눈에 비교하기 쉽다.","scoring_points":["표가 수·합계를 알기 쉬움을 썼는가","그래프가 많고 적음을 비교하기 쉬움을 썼는가","예를 들었는가"]},"explanation":["표는 항목별 수와 합계를 쉽게 알 수 있어요.","그래프는 전체적인 비교를 쉽게 할 수 있어요.","예를 들어 설명하면 더 분명해요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_challenge#9','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',4,'essay','teacher','『수학익힘』 놀이터 문제예요. 2학년 학생들이 원하는 놀이기구를 조사한 그래프에서 ◯가 미끄럼틀 14개, 그네 5개, 회전 무대 13개, 시소 9개예요. 그래프를 보고 「선생님, 2학년 학생들이 가장 많이 원하는 ( )은/는 꼭 설치해 주세요. 하나 더 설치할 수 있다면 두 번째로 많이 원하는 ( )도 설치해 주시면 좋겠습니다.」의 빈칸을 채우고, 그렇게 쓴 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u5-C7","difficulty":4,"kind":"essay","stem":"『수학익힘』 놀이터 문제예요. 2학년 학생들이 원하는 놀이기구를 조사한 그래프에서 ◯가 미끄럼틀 14개, 그네 5개, 회전 무대 13개, 시소 9개예요. 그래프를 보고 「선생님, 2학년 학생들이 가장 많이 원하는 ( )은/는 꼭 설치해 주세요. 하나 더 설치할 수 있다면 두 번째로 많이 원하는 ( )도 설치해 주시면 좋겠습니다.」의 빈칸을 채우고, 그렇게 쓴 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 미끄럼틀, 회전 무대. 미끄럼틀을 원하는 학생이 14명으로 가장 많고, 회전 무대를 원하는 학생이 13명으로 미끄럼틀 다음으로 많기 때문이다.","scoring_points":["첫째 빈칸에 미끄럼틀을 썼는가","둘째 빈칸에 회전 무대를 썼는가","14명·13명을 견주어 까닭을 썼는가"]},"explanation":["가장 높이 쌓인 미끄럼틀이 14명으로 가장 많아요.","두 번째로 높은 회전 무대가 13명이에요.","그래프에서 알게 된 사실을 근거로 의견을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L05_challenge#10','math',2,2,'u5','L05','tb_g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',4,'mc','auto','동호네 반에서 공기놀이와 투호 놀이를 좋아하는 학생 수의 차이와 합을 차례로 쓴 것은 어느 것인가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X03']::text[],false,'{"seq":10,"concept":"M2-2-u5-C7","difficulty":4,"kind":"mc","stem":"동호네 반에서 공기놀이와 투호 놀이를 좋아하는 학생 수의 차이와 합을 차례로 쓴 것은 어느 것인가요?","options":[{"t":"1명, 17명","correct":true},{"t":"17명, 1명","mis":"M2-2-u5-X08"},{"t":"1명, 22명","mis":"M2-2-u5-X03"},{"t":"9명, 8명","mis":"M2-2-u5-X08"}],"explanation":["공기놀이 9명, 투호 놀이 8명이에요.","차이는 9 − 8 = 1명이에요.","합은 9 + 8 = 17명이에요 — 22명은 반 전체 합계예요."],"asset":{"type":"ftable","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","total":22}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L06_basic#1','math',2,2,'u5','L06','tb_g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',1,'sa','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u5-C8","difficulty":1,"kind":"sa","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["「보드게임」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／ → 6","그래서 빈칸은 6이에요."],"asset":{"type":"ftable","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,null,5],"unit":"명","vh":"학생 수","tally":[4,5,6,5]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. ／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["「공기놀이」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ → 5","그래서 빈칸은 5예요."],"asset":{"type":"ftable","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,null,6,5],"unit":"명","vh":"학생 수","tally":[4,5,6,5]},"answer":["5"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L06_basic#2','math',2,2,'u5','L06','tb_g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',1,'mc','auto','땅따먹기를 원하는 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01']::text[],true,'{"seq":2,"concept":"M2-2-u5-C8","difficulty":1,"kind":"mc","stem":"땅따먹기를 원하는 학생은 몇 명인가요?","options":[{"t":"4명","correct":true},{"t":"5명","mis":"M2-2-u5-X01"},{"t":"3명","mis":"M2-2-u5-X01"}],"explanation":["그래프에서 「땅따먹기」 칸에 ◯가 몇 개 그려졌는지 세어요.","땅따먹기를 원하는 학생은 4명이에요.","한 칸에 하나씩 — 그려진 수가 곧 그 항목의 수예요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","rows":10},"variant_rule":{"alt":[{"stem":"딱지치기를 원하는 학생은 몇 명인가요?","explanation":["그래프에서 「딱지치기」 칸에 ◯가 몇 개 그려졌는지 세어요.","딱지치기를 원하는 학생은 5명이에요.","한 칸에 하나씩 — 그려진 수가 곧 그 항목의 수예요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","rows":10},"options":[{"t":"5명","correct":true},{"t":"6명","mis":"M2-2-u5-X01"},{"t":"4명","mis":"M2-2-u5-X01"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L06_basic#3','math',2,2,'u5','L06','tb_g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',1,'sa','auto','표를 보고 그래프를 완성하려고 해요. 공기놀이 칸에는 ◯를 몇 개 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u5-C8","difficulty":1,"kind":"sa","stem":"표를 보고 그래프를 완성하려고 해요. 공기놀이 칸에는 ◯를 몇 개 그려야 하나요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["표에서 공기놀이는 5명이에요.","그래프의 수는 표의 수와 같아야 해요 — ◯를 5개 그려요.","맨 아래 칸부터 빠짐없이 한 칸에 하나씩 그려요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","table":true,"rows":10,"blank":[1]},"variant_rule":{"alt":[{"stem":"표를 보고 그래프를 완성하려고 해요. 보드게임 칸에는 ◯를 몇 개 그려야 하나요? 숫자로 쓰세요.","explanation":["표에서 보드게임은 6명이에요.","그래프의 수는 표의 수와 같아야 해요 — ◯를 6개 그려요.","맨 아래 칸부터 빠짐없이 한 칸에 하나씩 그려요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","table":true,"rows":10,"blank":[2]},"answer":["6","6개"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L06_basic#4','math',2,2,'u5','L06','tb_g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',1,'error','auto','민영이가 선생님께 쓴 쪽지예요. 「선생님, 우리 반 학생들이 원하는 교실 놀이를 조사하였습니다. 가장 많은 학생들이 원하는 교실 놀이는 ( )입니다.」 빈칸에 들어갈 놀이를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X07','M2-2-u5-X16']::text[],false,'{"seq":4,"concept":"M2-2-u5-C8","difficulty":1,"kind":"error","stem":"민영이가 선생님께 쓴 쪽지예요. 「선생님, 우리 반 학생들이 원하는 교실 놀이를 조사하였습니다. 가장 많은 학생들이 원하는 교실 놀이는 ( )입니다.」 빈칸에 들어갈 놀이를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「맨 앞에 있는 땅따먹기야.」","correct":true,"mis_target":"M2-2-u5-X07"},{"t":"가은 — 「◯가 가장 높은 보드게임이야.」","mis":"M2-2-u5-X16"},{"t":"태오 — 「표에서 6명으로 가장 많은 보드게임이야.」","mis":"M2-2-u5-X16"}],"explanation":["가장 많은 놀이는 수가 가장 큰 보드게임(6명)이에요.","맨 앞 칸이라고 가장 많은 게 아니에요.","땅따먹기는 4명으로 가장 적어요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","table":true,"rows":10}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L06_basic#5','math',2,2,'u5','L06','tb_g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',2,'mc','auto','가장 적은 학생들이 원하는 교실 놀이는 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],false,'{"seq":5,"concept":"M2-2-u5-C8","difficulty":2,"kind":"mc","stem":"가장 적은 학생들이 원하는 교실 놀이는 무엇인가요?","options":[{"t":"땅따먹기","correct":true},{"t":"보드게임","mis":"M2-2-u5-X09"},{"t":"공기놀이","mis":"M2-2-u5-X07"},{"t":"딱지치기","mis":"M2-2-u5-X07"}],"explanation":["그래프에서 ◯가 가장 낮게 쌓인 칸을 찾아요.","땅따먹기 4명, 공기놀이 5명, 보드게임 6명, 딱지치기 5명이에요 — 가장 적은 것은 땅따먹기(4명)예요.","「가장 적은」을 묻는지 다시 읽어요. 앞 칸이라고 많은 게 아니에요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","rows":10}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L06_basic#6','math',2,2,'u5','L06','tb_g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',2,'sa','auto','공기놀이를 원하는 학생과 딱지치기를 원하는 학생은 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u5-C8","difficulty":2,"kind":"sa","stem":"공기놀이를 원하는 학생과 딱지치기를 원하는 학생은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["10","10명"],"explanation":["공기놀이를 원하는 학생은 5명, 딱지치기를 원하는 학생은 5명이에요.","5 + 5 = 10이니 모두 10명이에요.","두 칸의 수를 더해요 — 전체 합계가 아니에요."],"asset":{"type":"ftable","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","total":20},"variant_rule":{"alt":[{"stem":"땅따먹기를 원하는 학생과 보드게임을 원하는 학생은 모두 몇 명인가요? 숫자로 쓰세요.","explanation":["땅따먹기를 원하는 학생은 4명, 보드게임을 원하는 학생은 6명이에요.","4 + 6 = 10이니 모두 10명이에요.","두 칸의 수를 더해요 — 전체 합계가 아니에요."],"asset":{"type":"ftable","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","total":20},"answer":["10","10명"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u5_L06_basic#7','math',2,2,'u5','L06','tb_g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',2,'mc','auto','표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?',ARRAY['M2-2-u5-X11']::text[],true,'{"seq":7,"concept":"M2-2-u5-C8","difficulty":2,"kind":"mc","stem":"표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?","options":[{"t":"땅따먹기 — 표는 4명인데 ◯를 5개 그렸다","correct":true},{"t":"공기놀이 — 표는 5명인데 ◯를 6개 그렸다","mis":"M2-2-u5-X11"},{"t":"보드게임 — 표는 6명인데 ◯를 5개 그렸다","mis":"M2-2-u5-X11"},{"t":"딱지치기 — 표는 5명인데 ◯를 6개 그렸다","mis":"M2-2-u5-X11"}],"explanation":["표에서 땅따먹기는 4명인데 그래프에는 ◯가 5개예요.","표와 그래프의 수는 반드시 같아야 해요.","다른 칸은 표의 수와 그래프의 수가 같아요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","table":true,"rows":10,"drawn":[5,5,6,5]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?","explanation":["표에서 보드게임은 6명인데 그래프에는 ◯가 5개예요.","표와 그래프의 수는 반드시 같아야 해요.","다른 칸은 표의 수와 그래프의 수가 같아요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","table":true,"rows":10,"drawn":[4,5,5,5]},"options":[{"t":"보드게임 — 표는 6명인데 ◯를 5개 그렸다","correct":true},{"t":"땅따먹기 — 표는 4명인데 ◯를 3개 그렸다","mis":"M2-2-u5-X11"},{"t":"공기놀이 — 표는 5명인데 ◯를 6개 그렸다","mis":"M2-2-u5-X11"},{"t":"딱지치기 — 표는 5명인데 ◯를 6개 그렸다","mis":"M2-2-u5-X11"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, 